cat > /workspace/impl/src/main.rs << 'RUSTEOF'
// svd2rust - Generate Rust register maps from SVD files
// Version 0.37.1

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::process;

mod config;
mod svd;
mod generate;
mod util;

use config::Config;

fn main() {
    let args: Vec<String> = env::args().collect();

    // Initialize logging
    let log_level = get_log_level(&args);
    setup_logging(log_level);

    match run(&args) {
        Ok(()) => {},
        Err(e) => {
            eprintln!("[ERROR svd2rust] {}", e);
            process::exit(1);
        }
    }
}

fn get_log_level(args: &[String]) -> Option<String> {
    // Check -l flag first
    for i in 0..args.len() {
        if (args[i] == "-l" || args[i] == "--log") && i + 1 < args.len() {
            return Some(args[i+1].clone());
        }
    }
    // Check RUST_LOG env var
    env::var("RUST_LOG").ok()
}

fn setup_logging(level: Option<String>) {
    // We'll use a simple global log level
    let level_str = level.unwrap_or_else(|| "info".to_string());
    let lvl = match level_str.to_lowercase().as_str() {
        "off" => 0,
        "error" => 1,
        "warn" => 2,
        "info" => 3,
        "debug" => 4,
        "trace" => 5,
        _ => 3,
    };
    // Store in thread-local or global - use env var approach
    unsafe {
        LOG_LEVEL = lvl;
        LOG_SOURCE = level_str;
    }
}

static mut LOG_LEVEL: i32 = 3;
static mut LOG_SOURCE: String = String::new();

pub fn log_error(module: &str, msg: &str) {
    unsafe {
        if LOG_LEVEL >= 1 {
            eprintln!("[ERROR {}] {}", module, msg);
        }
    }
}

pub fn log_warn(module: &str, msg: &str) {
    unsafe {
        if LOG_LEVEL >= 2 {
            eprintln!("[WARN  {}] {}", module, msg);
        }
    }
}

pub fn log_info(module: &str, msg: &str) {
    unsafe {
        if LOG_LEVEL >= 3 {
            eprintln!("[INFO  {}] {}", module, msg);
        }
    }
}

pub fn log_debug(module: &str, msg: &str) {
    unsafe {
        if LOG_LEVEL >= 4 {
            eprintln!("[DEBUG {}] {}", module, msg);
        }
    }
}

fn run(args: &[String]) -> Result<(), String> {
    let config = parse_args(args)?;

    log_debug("svd2rust", &format!("Current svd2rust config: {}", config.debug_display()));

    // Read input
    let input_data = if let Some(ref input_file) = config.input {
        log_info("svd2rust", "Parsing device from SVD file");
        fs::read_to_string(input_file)
            .map_err(|e| format!("Failed to read input file: {}", e))?
    } else {
        log_info("svd2rust", "Parsing device from SVD file");
        let mut buf = String::new();
        io::stdin().read_to_string(&mut buf)
            .map_err(|e| format!("Failed to read stdin: {}", e))?;
        buf
    };

    // Parse SVD
    let device = parse_svd(&input_data, &config)?;

    log_info("svd2rust", "Rendering device");

    // Generate output
    let output = generate::render_device(&device, &config)?;

    // Write output files
    write_output(&output, &config)?;

    Ok(())
}

fn parse_svd(data: &str, config: &Config) -> Result<svd::Device, String> {
    match config.source_type.as_str() {
        "xml" => {
            svd::parse_xml(data, config.strict)
                .map_err(|e| {
                    let msg = format!("Error parsing SVD XML file\n    \n    Caused by:\n        {}", e);
                    log_error("svd2rust", &msg);
                    process::exit(1);
                })
        },
        "yaml" => {
            let _ = svd::parse_yaml(data)
                .map_err(|e| {
                    let msg = format!("Error parsing SVD YAML file\n    \n    Caused by:\n        {}", e);
                    log_error("svd2rust", &msg);
                    process::exit(1);
                });
            unreachable!()
        },
        "json" => {
            Err("JSON source type not fully implemented".to_string())
        },
        _ => Err(format!("Unknown source type: {}", config.source_type)),
    }
}

fn write_output(output: &generate::Output, config: &Config) -> Result<(), String> {
    let output_dir = config.output_dir.as_deref();

    let write_file = |filename: &str, content: &str| -> Result<(), String> {
        let path = if let Some(dir) = output_dir {
            PathBuf::from(dir).join(filename)
        } else {
            PathBuf::from(filename)
        };

        fs::write(&path, content)
            .map_err(|e| {
                let msg = format!("Couldn't create output file: {}", e);
                eprintln!("thread 'main' ({}) panicked at src/main.rs:361:54:\n{}", 
                    std::process::id(), msg);
                eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                process::exit(101);
            })
    };

    let main_filename = if config.make_mod { "mod.rs" } else { "lib.rs" };
    write_file(main_filename, &output.lib_rs)?;

    if let Some(ref generic_content) = output.generic_rs {
        write_file("generic.rs", generic_content)?;
    }

    write_file("build.rs", &output.build_rs)?;
    write_file("device.x", &output.device_x)?;

    Ok(())
}

fn parse_args(args: &[String]) -> Result<Config, String> {
    let mut config = Config::default();
    let mut i = 1;

    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                print_help(false);
                process::exit(0);
            },
            "--help" => {
                print_help(true);
                process::exit(0);
            },
            "-V" | "--version" => {
                println!("svd2rust 0.37.1 (e29353d 2026-03-03)");
                process::exit(0);
            },
            "-i" => {
                i += 1;
                if i >= args.len() { return Err("Expected FILE after -i".to_string()); }
                config.input = Some(args[i].clone());
            },
            "-o" | "--output-dir" => {
                i += 1;
                if i >= args.len() { return Err("Expected PATH after -o".to_string()); }
                config.output_dir = Some(args[i].clone());
            },
            "-c" | "--config" => {
                i += 1;
                if i >= args.len() { return Err("Expected TOML_FILE after -c".to_string()); }
                let toml_content = fs::read_to_string(&args[i])
                    .map_err(|e| format!("Failed to read config file: {}", e))?;
                config.apply_toml(&toml_content)?;
            },
            "--settings" => {
                i += 1;
                if i >= args.len() { return Err("Expected YAML_FILE after --settings".to_string()); }
                config.settings_file = Some(args[i].clone());
                // Load settings YAML
                let yaml_content = fs::read_to_string(&args[i])
                    .map_err(|e| format!("Failed to read settings file: {}", e))?;
                config.apply_settings_yaml(&yaml_content)?;
            },
            "--edition" => {
                i += 1;
                if i >= args.len() { return Err("Expected YEAR after --edition".to_string()); }
                match args[i].as_str() {
                    "2021" => config.edition = "E2021".to_string(),
                    "2024" => config.edition = "E2024".to_string(),
                    other => {
                        let msg = format!("Failed to deserialize value\n    \n    Caused by:\n        unknown variant `{}`, expected `2021` or `2024`", other);
                        log_error("svd2rust", &msg);
                        process::exit(1);
                    }
                }
            },
            "--target" => {
                i += 1;
                if i >= args.len() { return Err("Expected ARCH after --target".to_string()); }
                match args[i].as_str() {
                    "cortex-m" => config.target = "CortexM".to_string(),
                    "msp430" => config.target = "Msp430".to_string(),
                    "riscv" => config.target = "Riscv".to_string(),
                    "xtensa-lx" => config.target = "XtensaLx".to_string(),
                    "mips" => config.target = "Mips".to_string(),
                    "none" => config.target = "None".to_string(),
                    other => {
                        let msg = format!("Failed to deserialize value\n    \n    Caused by:\n        unknown variant `{}`, expected one of `cortex-m`, `msp430`, `riscv`, `xtensa-lx`, `mips`, `none`", other);
                        log_error("svd2rust", &msg);
                        process::exit(1);
                    }
                }
            },
            "--atomics" => config.atomics = true,
            "--atomics-feature" => {
                i += 1;
                if i >= args.len() { return Err("Expected FEATURE after --atomics-feature".to_string()); }
                config.atomics_feature = Some(args[i].clone());
            },
            "--ignore-groups" => config.ignore_groups = true,
            "--keep-list" => config.keep_list = true,
            "-g" | "--generic-mod" => config.generic_mod = true,
            "--feature-group" => config.feature_group = true,
            "--feature-peripheral" => config.feature_peripheral = true,
            "-f" | "--ident-format" => {
                i += 1;
                if i >= args.len() { return Err("Expected ident_format after -f".to_string()); }
                config.apply_ident_format(&args[i])?;
            },
            "--ident-formats-theme" => {
                i += 1;
                if i >= args.len() { return Err("Expected THEME after --ident-formats-theme".to_string()); }
                config.ident_formats_theme = Some(args[i].clone());
                config.apply_theme(&args[i])?;
            },
            "--field-names-for-enums" => config.field_names_for_enums = true,
            "--max-cluster-size" => config.max_cluster_size = true,
            "--impl-debug" => config.impl_debug = true,
            "--impl-debug-feature" => {
                i += 1;
                if i >= args.len() { return Err("Expected FEATURE after --impl-debug-feature".to_string()); }
                config.impl_debug_feature = Some(args[i].clone());
            },
            "--impl-defmt" => {
                i += 1;
                if i >= args.len() { return Err("Expected FEATURE after --impl-defmt".to_string()); }
                config.impl_defmt = Some(args[i].clone());
            },
            "-m" | "--make-mod" => config.make_mod = true,
            "--skip-crate-attributes" => config.skip_crate_attributes = true,
            "-s" | "--strict" => config.strict = true,
            "--source-type" => {
                i += 1;
                if i >= args.len() { return Err("Expected source_type after --source-type".to_string()); }
                match args[i].as_str() {
                    "xml" => config.source_type = "xml".to_string(),
                    "yaml" => config.source_type = "yaml".to_string(),
                    "json" => config.source_type = "json".to_string(),
                    other => {
                        let msg = format!("Failed to deserialize value\n    \n    Caused by:\n        unknown variant `{}`, expected one of `xml`, `yaml`, `json`", other);
                        log_error("svd2rust", &msg);
                        process::exit(1);
                    }
                }
            },
            "--reexport-core-peripherals" => config.reexport_core_peripherals = true,
            "--reexport-interrupt" => config.reexport_interrupt = true,
            "-b" | "--base-address-shift" => {
                i += 1;
                if i >= args.len() { return Err("Expected base_address_shift after -b".to_string()); }
                config.base_address_shift = args[i].parse::<i64>()
                    .map_err(|_| format!("Invalid base address shift: {}", args[i]))?;
            },
            "-l" | "--log" => {
                i += 1;
                if i >= args.len() { return Err("Expected log_level after -l".to_string()); }
                // Already handled
            },
            other => {
                if other.starts_with('-') {
                    return Err(format!("Unknown argument: {}", other));
                }
                // Could be positional argument (input file)
                config.input = Some(other.to_string());
            }
        }
        i += 1;
    }

    Ok(config)
}

fn print_help(long: bool) {
    print!(r#"Generate a Rust API from SVD files

Usage: executable [OPTIONS]

Options:
  -i <FILE>
          Input SVD file

  -o, --output-dir <PATH>
          Directory to place generated files

  -c, --config <TOML_FILE>
          Config TOML file

      --settings <YAML_FILE>
          Target-specific settings YAML file

      --edition <YEAR>
          Rust edition of generated code

      --target <ARCH>
          Target architecture

      --atomics
          Generate atomic register modification API

      --atomics-feature <FEATURE>
          add feature gating for atomic register modification API

      --ignore-groups
          Don't add alternateGroup name as prefix to register name

      --keep-list
          Keep lists when generating code of dimElement, instead of trying to generate arrays

  -g, --generic-mod
          Push generic mod in separate file

      --feature-group
          Use group_name of peripherals as feature

      --feature-peripheral
          Use independent cfg feature flags for each peripheral

  -f, --ident-format <ident_format>
          Specify `-f type:prefix:case:suffix` to change default ident formatting.
          Allowed values of `type` are ["peripheral", "peripheral_mod", "peripheral_singleton", "enum_value_accessor", "enum_read_name", "enum_name", "field_accessor", "cluster_accessor", "peripheral_spec", "cluster_mod", "cluster", "register_accessor", "field_reader", "register", "enum_write_name", "peripheral_feature", "register_spec", "enum_value", "register_mod", "interrupt", "field_writer"].
          Allowed cases are `unchanged` (''), `pascal` ('p'), `constant` ('c') and `snake` ('s').


      --ident-formats-theme <THEME>
          A set of `ident_format` settings. `new` or `legacy`

      --field-names-for-enums
          Use field name for enumerations even when enumeratedValues has a name

      --max-cluster-size
          Use array increment for cluster size

      --impl-debug
          implement Debug for readable blocks and registers

      --impl-debug-feature <FEATURE>
          Add feature gating for block and register debug implementation

      --impl-defmt <FEATURE>
          Add automatic defmt implementation for enumerated values

  -m, --make-mod
          Create mod.rs instead of lib.rs, without inner attributes

      --skip-crate-attributes
          Do not generate crate attributes

  -s, --strict
          Make advanced checks due to parsing SVD

      --source-type <source_type>
          Specify file/stream format

      --reexport-core-peripherals
          For Cortex-M target reexport peripherals from cortex-m crate

      --reexport-interrupt
          Reexport interrupt macro from cortex-m-rt like crates

  -b, --base-address-shift <base_address_shift>
          Add offset to all base addresses on all peripherals in the SVD file.
          Useful for soft-cores where the peripheral address range isn't necessarily fixed.
          Ignore this option if you are not building your own FPGA based soft-cores.

  -l, --log <log_level>
          Choose which messages to log (overrides RUST_LOG)

          [possible values: off, error, warn, info, debug, trace]

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version
"#);
}

RUSTEOF
echo "Created main.rs"

