fn setup_logging(level: Option<String>) {
    // We'll use a simple global log level
    let level_str = level.unwrap_or_else(|| "info".to_string());
    let lvl = match level_str.to_lowercase().as_str() {
        "off" => 0,
        "error" => 1,
        "warn" => 2,
        "info" => 3,
        "debug" => 4,
        "trace" => 5,
        _ => 3,
    };
    // Store in thread-local or global - use env var approach
    unsafe {
        LOG_LEVEL = lvl;
        LOG_SOURCE = level_str;
    }
}

static mut LOG_LEVEL: i32 = 3;
static mut LOG_SOURCE: String = String::new();

pub fn log_error(module: &str, msg: &str) {
    unsafe {
        if LOG_LEVEL >= 1 {
            eprintln!("[ERROR {}] {}", module, msg);
        }
    }
}

pub fn log_warn(module: &str, msg: &str) {
    unsafe {
        if LOG_LEVEL >= 2 {
            eprintln!("[WARN  {}] {}", module, msg);
        }
    }
}

pub fn log_info(module: &str, msg: &str) {
    unsafe {
        if LOG_LEVEL >= 3 {
            eprintln!("[INFO  {}] {}", module, msg);
        }
    }
}

pub fn log_debug(module: &str, msg: &str) {
    unsafe {
        if LOG_LEVEL >= 4 {
            eprintln!("[DEBUG {}] {}", module, msg);
        }
    }
