fn run(args: &[String]) -> Result<(), String> {
    let config = parse_args(args)?;

    log_debug("svd2rust", &format!("Current svd2rust config: {}", config.debug_display()));

    // Read input
    let input_data = if let Some(ref input_file) = config.input {
        log_info("svd2rust", "Parsing device from SVD file");
        fs::read_to_string(input_file)
            .map_err(|e| format!("Failed to read input file: {}", e))?
    } else {
        log_info("svd2rust", "Parsing device from SVD file");
        let mut buf = String::new();
        io::stdin().read_to_string(&mut buf)
            .map_err(|e| format!("Failed to read stdin: {}", e))?;
        buf
    };

    // Parse SVD
    let device = parse_svd(&input_data, &config)?;

    log_info("svd2rust", "Rendering device");

    // Generate output
    let output = generate::render_device(&device, &config)?;

    // Write output files
    write_output(&output, &config)?;

    Ok(())
}

fn parse_svd(data: &str, config: &Config) -> Result<svd::Device, String> {
    match config.source_type.as_str() {
        "xml" => {
            svd::parse_xml(data, config.strict)
                .map_err(|e| {
                    let msg = format!("Error parsing SVD XML file\n    \n    Caused by:\n        {}", e);
                    log_error("svd2rust", &msg);
                    process::exit(1);
                })
        },
        "yaml" => {
            let _ = svd::parse_yaml(data)
                .map_err(|e| {
                    let msg = format!("Error parsing SVD YAML file\n    \n    Caused by:\n        {}", e);
                    log_error("svd2rust", &msg);
                    process::exit(1);
                });
            unreachable!()
        },
        "json" => {
            Err("JSON source type not fully implemented".to_string())
        },
        _ => Err(format!("Unknown source type: {}", config.source_type)),
    }
}

fn write_output(output: &generate::Output, config: &Config) -> Result<(), String> {
    let output_dir = config.output_dir.as_deref();

    let write_file = |filename: &str, content: &str| -> Result<(), String> {
        let path = if let Some(dir) = output_dir {
            PathBuf::from(dir).join(filename)
        } else {
            PathBuf::from(filename)
        };

        fs::write(&path, content)
            .map_err(|e| {
                let msg = format!("Couldn't create output file: {}", e);
                eprintln!("thread 'main' ({}) panicked at src/main.rs:361:54:\n{}", 
                    std::process::id(), msg);
                eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                process::exit(101);
            })
    };

    let main_filename = if config.make_mod { "mod.rs" } else { "lib.rs" };
    write_file(main_filename, &output.lib_rs)?;

    if let Some(ref generic_content) = output.generic_rs {
        write_file("generic.rs", generic_content)?;
    }

    write_file("build.rs", &output.build_rs)?;
    write_file("device.x", &output.device_x)?;

    Ok(())
}

