impl Config {
    pub fn apply_toml(&mut self, content: &str) -> Result<(), String> {
        // Simple TOML parser for config
        for line in content.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            if let Some(eq_pos) = line.find('=') {
                let key = line[..eq_pos].trim();
                let value = line[eq_pos+1..].trim().trim_matches('"').trim_matches('\'');
                match key {
                    "target" => {
                        match value {
                            "cortex-m" => self.target = "CortexM".to_string(),
                            "msp430" => self.target = "Msp430".to_string(),
                            "riscv" => self.target = "Riscv".to_string(),
                            "xtensa-lx" => self.target = "XtensaLx".to_string(),
                            "mips" => self.target = "Mips".to_string(),
                            "none" => self.target = "None".to_string(),
                            _ => {}
                        }
                    },
                    "atomics" => {
                        if value == "true" { self.atomics = true; }
                    },
                    "generic_mod" => {
                        if value == "true" { self.generic_mod = true; }
                    },
                    "make_mod" => {
                        if value == "true" { self.make_mod = true; }
                    },
                    "strict" => {
                        if value == "true" { self.strict = true; }
                    },
                    "edition" => {
                        match value {
                            "2021" => self.edition = "E2021".to_string(),
                            "2024" => self.edition = "E2024".to_string(),
                            _ => {}
                        }
                    },
                    _ => {}
                }
            }
        }
        Ok(())
    }

    pub fn apply_settings_yaml(&mut self, _content: &str) -> Result<(), String> {
        // Parse settings YAML - minimal implementation
        Ok(())
    }

    pub fn apply_ident_format(&mut self, spec: &str) -> Result<(), String> {
        // Format: type:prefix:case:suffix
        let parts: Vec<&str> = spec.splitn(4, ':').collect();
        if parts.len() < 2 {
            return Err(format!("Invalid ident format: {}", spec));
        }
        let type_name = parts[0];
        let prefix = if parts.len() > 1 { parts[1] } else { "" };
        let case_str = if parts.len() > 2 { parts[2] } else { "" };
        let suffix = if parts.len() > 3 { parts[3] } else { "" };

        let case = match case_str {
            "" => None,
            "p" | "pascal" => Some("Pascal"),
            "c" | "constant" => Some("Constant"),
            "s" | "snake" => Some("Snake"),
            other => return Err(format!("Unknown case: {}", other)),
        };

        self.ident_formats.insert(type_name.to_string(), IdentFormat::new(case, prefix, suffix));
        Ok(())
    }

    pub fn apply_theme(&mut self, theme: &str) -> Result<(), String> {
        match theme {
            "new" => {
                // Already default
            },
            "legacy" => {
                // Apply legacy theme
                // In legacy, enum_write_name suffix is "W" not "WO"
                self.ident_formats.insert("enum_write_name".to_string(), IdentFormat::new(Some("Pascal"), "", "W"));
                // Other legacy differences...
            },
            _ => return Err(format!("Unknown theme: {}", theme)),
        }
        Ok(())
    }

