        let parts: Vec<&str> = spec.splitn(4, ':').collect();
        if parts.len() < 2 {
            return Err(format!("Invalid ident format: {}", spec));
        }
        let type_name = parts[0];
        let prefix = if parts.len() > 1 { parts[1] } else { "" };
        let case_str = if parts.len() > 2 { parts[2] } else { "" };
        let suffix = if parts.len() > 3 { parts[3] } else { "" };

        let case = match case_str {
            "" => None,
            "p" | "pascal" => Some("Pascal"),
            "c" | "constant" => Some("Constant"),
            "s" | "snake" => Some("Snake"),
            other => return Err(format!("Unknown case: {}", other)),
