// Minimal XML parser for SVD files
use super::*;

pub fn parse_xml(data: &str, _strict: bool) -> Result<Device, String> {
    let mut parser = XmlParser::new(data);
    parser.parse_device()
}

struct XmlParser<'a> {
    data: &'a str,
    pos: usize,
}

impl<'a> XmlParser<'a> {
    fn new(data: &'a str) -> Self {
        XmlParser { data, pos: 0 }
    }

    fn parse_device(&mut self) -> Result<Device, String> {
        // Skip XML declaration
        self.skip_whitespace();
        if self.data[self.pos..].starts_with("<?") {
            self.skip_to_end_of_processing_instruction()?;
        }
        self.skip_whitespace();

        // Skip comments
        loop {
            self.skip_whitespace();
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
            } else {
                break;
            }
        }

        // Parse <device>
        let (tag, attrs) = self.parse_open_tag()?;
        if tag != "device" {
            return Err(format!("Expected <device> tag, got <{}>", tag));
        }

        let mut name = String::new();
        let mut version = None;
        let mut description = None;
        let mut address_unit_bits = 8u32;
        let mut width = 32u32;
        let mut default_size = 32u32;
        let mut default_reset_value = 0u64;
        let mut default_reset_mask = 0xFFFFFFFFu64;
        let mut default_access: Option<Access> = None;
        let mut peripherals = Vec::new();

        loop {
            self.skip_whitespace();
            if self.data[self.pos..].starts_with("</") {
                let close = self.parse_close_tag()?;
                if close == "device" { break; }
                return Err(format!("Unexpected close tag </{}>", close));
            }
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
                continue;
            }

            let (child_tag, child_attrs) = self.parse_open_tag()?;
            match child_tag.as_str() {
                "name" => name = self.parse_text()?,
                "version" => version = Some(self.parse_text()?),
                "description" => description = Some(self.parse_text()?),
                "addressUnitBits" => {
                    address_unit_bits = self.parse_text()?.trim().parse().unwrap_or(8);
                },
                "width" => {
                    width = self.parse_text()?.trim().parse().unwrap_or(32);
                    // Also update default_size
                    default_size = width;
                },
                "size" => {
                    default_size = self.parse_text()?.trim().parse().unwrap_or(32);
                },
                "resetValue" => {
                    default_reset_value = parse_hex_or_dec(self.parse_text()?.trim())?;
                },
                "resetMask" => {
                    default_reset_mask = parse_hex_or_dec(self.parse_text()?.trim())?;
                },
                "access" => {
                    let access_str = self.parse_text()?;
                    default_access = Access::from_str(access_str.trim());
                },
                "peripherals" => {
                    peripherals = self.parse_peripherals(default_size, default_reset_value, default_reset_mask, default_access.clone())?;
                    // parse_peripherals already consumes </peripherals>
                    continue;
                },
                _ => {
                    // Skip unknown elements
                    self.skip_element(&child_tag)?;
                    continue;
                }
            }
            if child_tag != "peripherals" {
                let close = self.parse_close_tag()?;
                // ignore close tag name mismatch for simplicity
            }
        }

        Ok(Device {
            name,
            version,
            description,
            address_unit_bits,
            width,
            default_register_size: default_size,
            default_reset_value,
            default_reset_mask,
            default_access,
            peripherals,
        })
    }

    fn parse_peripherals(&mut self, default_size: u32, default_reset_value: u64, default_reset_mask: u64, default_access: Option<Access>) -> Result<Vec<Peripheral>, String> {
        let mut peripherals = Vec::new();

        loop {
            self.skip_whitespace();
            if self.data[self.pos..].starts_with("</") {
                let close = self.parse_close_tag()?;
                break;
            }
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
                continue;
            }

            let (tag, attrs) = self.parse_open_tag()?;
            if tag == "peripheral" {
                let derived_from = attrs.get("derivedFrom").cloned();
                let p = self.parse_peripheral(default_size, default_reset_value, default_reset_mask, default_access.clone(), derived_from)?;
                peripherals.push(p);
            } else {
                self.skip_element(&tag)?;
            }
        }

        Ok(peripherals)
    }

    fn parse_peripheral(&mut self, def_size: u32, def_reset: u64, def_mask: u64, def_access: Option<Access>, derived_from: Option<String>) -> Result<Peripheral, String> {
        let mut name = String::new();
        let mut description = None;
        let mut group_name = None;
        let mut base_address = 0u64;
        let mut registers = Vec::new();
        let mut interrupts = Vec::new();
        let mut address_block = None;
        let mut per_size = None;
        let mut per_reset = None;
        let mut per_mask = None;
        let mut per_access = None;

        loop {
            self.skip_whitespace();
            if self.data[self.pos..].starts_with("</") {
                let close = self.parse_close_tag()?;
                break;
            }
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
                continue;
            }

            let (tag, attrs) = self.parse_open_tag()?;
            match tag.as_str() {
                "name" => name = self.parse_text()?,
                "description" => description = Some(self.parse_text()?),
                "groupName" => group_name = Some(self.parse_text()?),
                "baseAddress" => {
                    base_address = parse_hex_or_dec(self.parse_text()?.trim())?;
                },
                "size" => {
                    per_size = Some(self.parse_text()?.trim().parse::<u32>().unwrap_or(32));
                },
                "resetValue" => {
                    per_reset = Some(parse_hex_or_dec(self.parse_text()?.trim())?);
                },
                "resetMask" => {
                    per_mask = Some(parse_hex_or_dec(self.parse_text()?.trim())?);
                },
                "access" => {
                    per_access = Access::from_str(self.parse_text()?.trim());
                },
                "addressBlock" => {
                    address_block = Some(self.parse_address_block()?);
                    continue;
                },
                "interrupt" => {
                    let irq = self.parse_interrupt()?;
                    interrupts.push(irq);
                    continue;
                },
                "registers" => {
                    let eff_size = per_size.unwrap_or(def_size);
                    let eff_reset = per_reset.unwrap_or(def_reset);
                    let eff_mask = per_mask.unwrap_or(def_mask);
                    let eff_access = per_access.clone().or(def_access.clone());
                    registers = self.parse_registers(eff_size, eff_reset, eff_mask, eff_access)?;
                    continue;
                },
                _ => {
                    self.skip_element(&tag)?;
                    continue;
                }
            }
            let _ = self.parse_close_tag();
        }

        Ok(Peripheral {
            name,
            description,
            group_name,
            base_address,
            derived_from,
            registers,
            interrupts,
            address_block,
            default_register_size: per_size,
            default_reset_value: per_reset,
            default_reset_mask: per_mask,
            default_access: per_access,
        })
    }

    fn parse_address_block(&mut self) -> Result<AddressBlock, String> {
        let mut offset = 0u64;
        let mut size = 0u64;
        let mut usage = String::new();

        loop {
            self.skip_whitespace();
            if self.data[self.pos..].starts_with("</") {
                let _ = self.parse_close_tag()?;
                break;
            }
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
                continue;
            }
            let (tag, _) = self.parse_open_tag()?;
            match tag.as_str() {
                "offset" => { offset = parse_hex_or_dec(self.parse_text()?.trim())?; },
                "size" => { size = parse_hex_or_dec(self.parse_text()?.trim())?; },
                "usage" => { usage = self.parse_text()?; },
                _ => { self.skip_element(&tag)?; continue; }
            }
            let _ = self.parse_close_tag();
        }

        Ok(AddressBlock { offset, size, usage })
    }

    fn parse_interrupt(&mut self) -> Result<Interrupt, String> {
        let mut name = String::new();
        let mut description = None;
        let mut value = 0u32;

        loop {
            self.skip_whitespace();
            if self.data[self.pos..].starts_with("</") {
                let _ = self.parse_close_tag()?;
                break;
            }
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
                continue;
            }
            let (tag, _) = self.parse_open_tag()?;
            match tag.as_str() {
                "name" => { name = self.parse_text()?; },
                "description" => { description = Some(self.parse_text()?); },
                "value" => { value = self.parse_text()?.trim().parse().unwrap_or(0); },
                _ => { self.skip_element(&tag)?; continue; }
            }
            let _ = self.parse_close_tag();
        }

        Ok(Interrupt { name, description, value })
    }

    fn parse_registers(&mut self, def_size: u32, def_reset: u64, def_mask: u64, def_access: Option<Access>) -> Result<Vec<RegisterOrCluster>, String> {
        let mut items = Vec::new();

        loop {
            self.skip_whitespace();
            if self.data[self.pos..].starts_with("</") {
                let _ = self.parse_close_tag()?;
                break;
            }
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
                continue;
            }

            let (tag, attrs) = self.parse_open_tag()?;
            match tag.as_str() {
                "register" => {
                    let derived_from = attrs.get("derivedFrom").cloned();
                    let r = self.parse_register(def_size, def_reset, def_mask, def_access.clone(), derived_from)?;
                    items.push(r);
                },
                "cluster" => {
                    let derived_from = attrs.get("derivedFrom").cloned();
                    let c = self.parse_cluster(def_size, def_reset, def_mask, def_access.clone(), derived_from)?;
                    items.push(c);
                },
                _ => {
                    self.skip_element(&tag)?;
                }
            }
        }

        Ok(items)
    }

    fn parse_register(&mut self, def_size: u32, def_reset: u64, def_mask: u64, def_access: Option<Access>, derived_from: Option<String>) -> Result<RegisterOrCluster, String> {
        let mut name = String::new();
        let mut display_name = None;
        let mut description = None;
        let mut alternate_group = None;
        let mut alternate_register = None;
        let mut address_offset = 0u64;
        let mut size = None;
        let mut access = None;
        let mut reset_value = None;
        let mut reset_mask = None;
        let mut modified_write_values = None;
        let mut read_action = None;
        let mut fields = Vec::new();
        let mut dim = None;
        let mut dim_increment = None;
        let mut dim_index = None;

        loop {
            self.skip_whitespace();
            if self.data[self.pos..].starts_with("</") {
                let _ = self.parse_close_tag()?;
                break;
            }
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
                continue;
            }

            let (tag, _) = self.parse_open_tag()?;
            match tag.as_str() {
                "name" => { name = self.parse_text()?.trim().to_string(); },
                "displayName" => { display_name = Some(self.parse_text()?); },
                "description" => { description = Some(self.parse_text()?); },
                "alternateGroup" => { alternate_group = Some(self.parse_text()?); },
                "alternateRegister" => { alternate_register = Some(self.parse_text()?); },
                "addressOffset" => { address_offset = parse_hex_or_dec(self.parse_text()?.trim())?; },
                "size" => { size = Some(self.parse_text()?.trim().parse::<u32>().unwrap_or(32)); },
                "access" => { access = Access::from_str(self.parse_text()?.trim()); },
                "resetValue" => { reset_value = Some(parse_hex_or_dec(self.parse_text()?.trim())?); },
                "resetMask" => { reset_mask = Some(parse_hex_or_dec(self.parse_text()?.trim())?); },
                "modifiedWriteValues" => {
                    modified_write_values = ModifiedWriteValues::from_str(self.parse_text()?.trim());
                },
                "readAction" => {
                    read_action = ReadAction::from_str(self.parse_text()?.trim());
                },
                "fields" => {
                    fields = self.parse_fields()?;
                    continue;
                },
                "dim" => { dim = Some(self.parse_text()?.trim().parse::<u32>().unwrap_or(1)); },
                "dimIncrement" => { dim_increment = Some(parse_hex_or_dec(self.parse_text()?.trim())? as u32); },
                "dimIndex" => { dim_index = Some(parse_dim_index(&self.parse_text()?)); },
                _ => { self.skip_element(&tag)?; continue; }
            }
            let _ = self.parse_close_tag();
        }

        let eff_size = size.unwrap_or(def_size);
        let eff_reset = reset_value.unwrap_or(def_reset);
        let eff_mask = reset_mask.unwrap_or(def_mask);
        let eff_access = access.unwrap_or_else(|| def_access.clone().unwrap_or(Access::ReadWrite));

        if let (Some(d), Some(di)) = (dim, dim_increment) {
            Ok(RegisterOrCluster::RegisterArray(RegisterArray {
                name,
                description,
                address_offset,
                size: eff_size,
                access: eff_access,
                reset_value: eff_reset,
                reset_mask: eff_mask,
                dim: d,
                dim_increment: di,
                dim_index,
                modified_write_values,
                read_action,
                fields,
                derived_from,
            }))
        } else {
            Ok(RegisterOrCluster::Register(Register {
                name,
                display_name,
                description,
                alternate_group,
                alternate_register,
                address_offset,
                size: eff_size,
                access: eff_access,
                reset_value: eff_reset,
                reset_mask: eff_mask,
                modified_write_values,
                read_action,
                fields,
                derived_from,
            }))
        }
    }

    fn parse_cluster(&mut self, def_size: u32, def_reset: u64, def_mask: u64, def_access: Option<Access>, derived_from: Option<String>) -> Result<RegisterOrCluster, String> {
        let mut name = String::new();
        let mut description = None;
        let mut address_offset = 0u64;
        let mut registers = Vec::new();
        let mut dim = None;
        let mut dim_increment = None;
        let mut dim_index = None;
        let mut cl_size = None;
        let mut cl_reset = None;
        let mut cl_mask = None;
        let mut cl_access = None;

        loop {
            self.skip_whitespace();
            if self.data[self.pos..].starts_with("</") {
                let _ = self.parse_close_tag()?;
                break;
            }
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
                continue;
            }

            let (tag, _) = self.parse_open_tag()?;
            match tag.as_str() {
                "name" => { name = self.parse_text()?.trim().to_string(); },
                "description" => { description = Some(self.parse_text()?); },
                "addressOffset" => { address_offset = parse_hex_or_dec(self.parse_text()?.trim())?; },
                "size" => { cl_size = Some(self.parse_text()?.trim().parse::<u32>().unwrap_or(32)); },
                "resetValue" => { cl_reset = Some(parse_hex_or_dec(self.parse_text()?.trim())?); },
                "resetMask" => { cl_mask = Some(parse_hex_or_dec(self.parse_text()?.trim())?); },
                "access" => { cl_access = Access::from_str(self.parse_text()?.trim()); },
                "register" | "cluster" => {
                    let (inner_tag, inner_attrs) = (tag.clone(), std::collections::HashMap::new());
                    // We already parsed the tag, need to handle nested elements
                    // This is tricky - we need to re-enter parsing
                    // Actually we already consumed the tag, so parse its content
                    let eff_size2 = cl_size.unwrap_or(def_size);
                    let eff_reset2 = cl_reset.unwrap_or(def_reset);
                    let eff_mask2 = cl_mask.unwrap_or(def_mask);
                    let eff_access2 = cl_access.clone().or(def_access.clone());
                    if tag == "register" {
                        let r = self.parse_register(eff_size2, eff_reset2, eff_mask2, eff_access2, None)?;
                        registers.push(r);
                    } else {
                        let c = self.parse_cluster(eff_size2, eff_reset2, eff_mask2, eff_access2, None)?;
                        registers.push(c);
                    }
                    continue;
                },
                "registers" => {
                    let eff_size2 = cl_size.unwrap_or(def_size);
                    let eff_reset2 = cl_reset.unwrap_or(def_reset);
                    let eff_mask2 = cl_mask.unwrap_or(def_mask);
                    let eff_access2 = cl_access.clone().or(def_access.clone());
                    registers = self.parse_registers(eff_size2, eff_reset2, eff_mask2, eff_access2)?;
                    continue;
                },
                "dim" => { dim = Some(self.parse_text()?.trim().parse::<u32>().unwrap_or(1)); },
                "dimIncrement" => { dim_increment = Some(parse_hex_or_dec(self.parse_text()?.trim())? as u32); },
                "dimIndex" => { dim_index = Some(parse_dim_index(&self.parse_text()?)); },
                _ => { self.skip_element(&tag)?; continue; }
            }
            let _ = self.parse_close_tag();
        }

        if let (Some(d), Some(di)) = (dim, dim_increment) {
            Ok(RegisterOrCluster::ClusterArray(ClusterArray {
                name,
                description,
                address_offset,
                registers,
                dim: d,
                dim_increment: di,
                dim_index,
                derived_from,
                default_register_size: cl_size,
                default_reset_value: cl_reset,
                default_reset_mask: cl_mask,
                default_access: cl_access,
            }))
        } else {
            Ok(RegisterOrCluster::Cluster(Cluster {
                name,
                description,
                address_offset,
                registers,
                derived_from,
                default_register_size: cl_size,
                default_reset_value: cl_reset,
                default_reset_mask: cl_mask,
                default_access: cl_access,
            }))
        }
    }

    fn parse_fields(&mut self) -> Result<Vec<Field>, String> {
        let mut fields = Vec::new();

        loop {
            self.skip_whitespace();
            if self.data[self.pos..].starts_with("</") {
                let _ = self.parse_close_tag()?;
                break;
            }
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
                continue;
            }

            let (tag, _) = self.parse_open_tag()?;
            if tag == "field" {
                let f = self.parse_field()?;
                fields.push(f);
            } else {
                self.skip_element(&tag)?;
            }
        }

        Ok(fields)
    }

    fn parse_field(&mut self) -> Result<Field, String> {
        let mut name = String::new();
        let mut description = None;
        let mut bit_offset = 0u32;
        let mut bit_width = 1u32;
        let mut lsb = None;
        let mut msb = None;
        let mut bit_range = None;
        let mut access = None;
        let mut enumerated_values = Vec::new();
        let mut modified_write_values = None;
        let mut read_action = None;

        loop {
            self.skip_whitespace();
            if self.data[self.pos..].starts_with("</") {
                let _ = self.parse_close_tag()?;
                break;
            }
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
                continue;
            }

            let (tag, _) = self.parse_open_tag()?;
            match tag.as_str() {
                "name" => { name = self.parse_text()?.trim().to_string(); },
                "description" => { description = Some(self.parse_text()?); },
                "bitOffset" => { bit_offset = self.parse_text()?.trim().parse().unwrap_or(0); },
                "bitWidth" => { bit_width = self.parse_text()?.trim().parse().unwrap_or(1); },
                "lsb" => { lsb = Some(self.parse_text()?.trim().parse::<u32>().unwrap_or(0)); },
                "msb" => { msb = Some(self.parse_text()?.trim().parse::<u32>().unwrap_or(0)); },
                "bitRange" => {
                    // Format: [msb:lsb]
                    let range_str = self.parse_text()?;
                    bit_range = parse_bit_range(&range_str);
                },
                "access" => { access = Access::from_str(self.parse_text()?.trim()); },
                "modifiedWriteValues" => {
                    modified_write_values = ModifiedWriteValues::from_str(self.parse_text()?.trim());
                },
                "readAction" => {
                    read_action = ReadAction::from_str(self.parse_text()?.trim());
                },
                "enumeratedValues" => {
                    let ev = self.parse_enumerated_values()?;
                    enumerated_values.push(ev);
                    continue;
                },
                _ => { self.skip_element(&tag)?; continue; }
            }
            let _ = self.parse_close_tag();
        }

        // Handle different bit range specifications
        if let Some((msb_val, lsb_val)) = bit_range {
            bit_offset = lsb_val;
            bit_width = msb_val - lsb_val + 1;
        } else if let (Some(lsb_val), Some(msb_val)) = (lsb, msb) {
            bit_offset = lsb_val;
            bit_width = msb_val - lsb_val + 1;
        }

        Ok(Field {
            name,
            description,
            bit_offset,
            bit_width,
            access,
            enumerated_values,
            modified_write_values,
            read_action,
        })
    }

    fn parse_enumerated_values(&mut self) -> Result<EnumeratedValues, String> {
        // Check if it's a self-closing tag or has a derivedFrom attribute
        // We already parsed the opening tag
        let mut name = None;
        let mut usage = None;
        let mut derived_from = None;
        let mut values = Vec::new();

        // Check if current position has attributes embedded
        // We parsed the opening tag already, but we need to get attributes from it
        // For now, parse child elements

        loop {
            self.skip_whitespace();
            if self.data[self.pos..].starts_with("</") {
                let _ = self.parse_close_tag()?;
                break;
            }
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
                continue;
            }

            let (tag, _) = self.parse_open_tag()?;
            match tag.as_str() {
                "name" => { name = Some(self.parse_text()?.trim().to_string()); },
                "usage" => {
                    let u = self.parse_text()?;
                    usage = match u.trim() {
                        "read" => Some(EnumUsage::Read),
                        "write" => Some(EnumUsage::Write),
                        "read-write" => Some(EnumUsage::ReadWrite),
                        _ => None,
                    };
                },
                "enumeratedValue" => {
                    let ev = self.parse_enumerated_value()?;
                    values.push(ev);
                    continue;
                },
                _ => { self.skip_element(&tag)?; continue; }
            }
            let _ = self.parse_close_tag();
        }

        Ok(EnumeratedValues {
            name,
            derived_from,
            usage,
            values,
        })
    }

    fn parse_enumerated_value(&mut self) -> Result<EnumeratedValue, String> {
        let mut name = String::new();
        let mut description = None;
        let mut value = None;
        let mut is_default = false;

        loop {
            self.skip_whitespace();
            if self.data[self.pos..].starts_with("</") {
                let _ = self.parse_close_tag()?;
                break;
            }
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
                continue;
            }

            let (tag, _) = self.parse_open_tag()?;
            match tag.as_str() {
                "name" => { name = self.parse_text()?.trim().to_string(); },
                "description" => { description = Some(self.parse_text()?); },
                "value" => {
                    let val_str = self.parse_text()?;
                    let val_str = val_str.trim();
                    if val_str == "#FFFFFFFF" || val_str == "default" {
                        is_default = true;
                    } else if val_str.starts_with("#") {
                        // Binary or masked value
                        let bin_str = &val_str[1..];
                        if bin_str.chars().all(|c| c == '0' || c == '1' || c == 'x' || c == 'X') {
                            // Parse binary with don't-cares
                            if let Ok(v) = u64::from_str_radix(&bin_str.replace('x', "0").replace('X', "0"), 2) {
                                value = Some(EnumValue::Value(v));
                            }
                        }
                    } else {
                        match parse_hex_or_dec(val_str) {
                            Ok(v) => value = Some(EnumValue::Value(v)),
                            Err(_) => {}
                        }
                    }
                },
                "isDefault" => {
                    if self.parse_text()?.trim() == "true" {
                        is_default = true;
                    }
                },
                _ => { self.skip_element(&tag)?; continue; }
            }
            let _ = self.parse_close_tag();
        }

        Ok(EnumeratedValue {
            name,
            description,
            value,
            is_default,
        })
    }

    fn skip_to_end_of_processing_instruction(&mut self) -> Result<(), String> {
        // Skip past ?>
        loop {
            if self.pos >= self.data.len() {
                return Err("Unexpected end of file in processing instruction".to_string());
            }
            if self.data[self.pos..].starts_with("?>") {
                self.pos += 2;
                return Ok(());
            }
            self.pos += 1;
        }
    }

    fn skip_comment(&mut self) -> Result<(), String> {
        // Skip <!-- ... -->
        if !self.data[self.pos..].starts_with("<!--") {
            return Ok(());
        }
        self.pos += 4;
        loop {
            if self.pos >= self.data.len() {
                return Err("Unexpected end of file in comment".to_string());
            }
            if self.data[self.pos..].starts_with("-->") {
                self.pos += 3;
                return Ok(());
            }
            self.pos += 1;
        }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.data.len() && self.data.as_bytes()[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn parse_open_tag(&mut self) -> Result<(String, HashMap<String, String>), String> {
        self.skip_whitespace();
        if self.pos >= self.data.len() || self.data.as_bytes()[self.pos] != b'<' {
            return Err(format!("Expected '<', got {:?} at pos {}", 
                self.data.get(self.pos..self.pos+10), self.pos));
        }
        self.pos += 1; // skip <

        // Read tag name
        let start = self.pos;
        while self.pos < self.data.len() {
            let c = self.data.as_bytes()[self.pos];
            if c == b' ' || c == b'>' || c == b'/' || c == b'\t' || c == b'\n' || c == b'\r' {
                break;
            }
            self.pos += 1;
        }
        let tag_name = self.data[start..self.pos].to_string();

        // Parse attributes
        let mut attrs = HashMap::new();
        loop {
            self.skip_whitespace();
            if self.pos >= self.data.len() { break; }
            let c = self.data.as_bytes()[self.pos];
            if c == b'>' {
                self.pos += 1;
                break;
            }
            if c == b'/' {
                // Self-closing tag />
                self.pos += 2; // skip />
                break;
            }
            // Parse attribute name
            let attr_start = self.pos;
            while self.pos < self.data.len() {
                let ac = self.data.as_bytes()[self.pos];
                if ac == b'=' || ac == b' ' || ac == b'>' || ac == b'/' || ac == b'\t' || ac == b'\n' || ac == b'\r' {
                    break;
                }
                self.pos += 1;
            }
            let attr_name = self.data[attr_start..self.pos].to_string();

            self.skip_whitespace();
            if self.pos >= self.data.len() || self.data.as_bytes()[self.pos] != b'=' {
                continue;
            }
            self.pos += 1; // skip =

            self.skip_whitespace();
            let quote = self.data.as_bytes()[self.pos];
            if quote != b'"' && quote != b'\'' {
                continue;
            }
            self.pos += 1;

            let val_start = self.pos;
            while self.pos < self.data.len() && self.data.as_bytes()[self.pos] != quote {
                self.pos += 1;
            }
            let attr_val = self.data[val_start..self.pos].to_string();
            self.pos += 1; // skip closing quote

            attrs.insert(attr_name, attr_val);
        }

        Ok((tag_name, attrs))
    }

    fn parse_close_tag(&mut self) -> Result<String, String> {
        self.skip_whitespace();
        if self.pos >= self.data.len() {
            return Ok(String::new());
        }
        if !self.data[self.pos..].starts_with("</") {
            // Might be an empty/self-closing that we already handled
            return Ok(String::new());
        }
        self.pos += 2; // skip </

        let start = self.pos;
        while self.pos < self.data.len() && self.data.as_bytes()[self.pos] != b'>' {
            self.pos += 1;
        }
        let tag_name = self.data[start..self.pos].trim().to_string();
        if self.pos < self.data.len() {
            self.pos += 1; // skip >
        }

        Ok(tag_name)
    }

    fn parse_text(&mut self) -> Result<String, String> {
        let start = self.pos;
        let mut text = String::new();

        while self.pos < self.data.len() {
            let c = self.data.as_bytes()[self.pos];
            if c == b'<' {
                break;
            }
            if c == b'&' {
                // Handle XML entities
                let entity_start = self.pos;
                self.pos += 1;
                let ent_name_start = self.pos;
                while self.pos < self.data.len() && self.data.as_bytes()[self.pos] != b';' {
                    self.pos += 1;
                }
                let ent_name = &self.data[ent_name_start..self.pos];
                self.pos += 1; // skip ;
                match ent_name {
                    "amp" => text.push('&'),
                    "lt" => text.push('<'),
                    "gt" => text.push('>'),
                    "quot" => text.push('"'),
                    "apos" => text.push('\''),
                    other => {
                        if other.starts_with('#') {
                            let num_str = &other[1..];
                            if let Ok(n) = u32::from_str_radix(num_str, 10) {
                                if let Some(ch) = char::from_u32(n) {
                                    text.push(ch);
                                }
                            }
                        } else {
                            text.push_str(&format!("&{};", ent_name));
                        }
                    }
                }
            } else {
                text.push(c as char);
                self.pos += 1;
            }
        }

        Ok(text)
    }

    fn skip_element(&mut self, tag: &str) -> Result<(), String> {
        // Skip until we find the matching </tag>
        let mut depth = 1;
        loop {
            if self.pos >= self.data.len() {
                return Ok(());
            }
            if self.data[self.pos..].starts_with("<!--") {
                self.skip_comment()?;
                continue;
            }
            if self.data[self.pos..].starts_with("</") {
                let close_start = self.pos + 2;
                let mut close_end = close_start;
                while close_end < self.data.len() && self.data.as_bytes()[close_end] != b'>' {
                    close_end += 1;
                }
                let close_tag = self.data[close_start..close_end].trim();
                self.pos = close_end + 1;
                if close_tag == tag {
                    depth -= 1;
                    if depth == 0 { return Ok(()); }
                }
            } else if self.data[self.pos..].starts_with('<') {
                let open_start = self.pos + 1;
                let mut open_end = open_start;
                // Skip to end of tag
                let mut in_attr = false;
                let mut attr_quote = 0u8;
                let mut is_self_closing = false;
                while open_end < self.data.len() {
                    let c = self.data.as_bytes()[open_end];
                    if in_attr {
                        if c == attr_quote { in_attr = false; }
                    } else {
                        if c == b'"' || c == b'\'' { in_attr = true; attr_quote = c; }
                        else if c == b'/' { is_self_closing = true; }
                        else if c == b'>' { break; }
                    }
                    open_end += 1;
                }
                // Get the tag name
                let mut tag_end = open_start;
                while tag_end < open_end {
                    let c = self.data.as_bytes()[tag_end];
                    if c == b' ' || c == b'>' || c == b'\t' || c == b'\n' || c == b'\r' || c == b'/' {
                        break;
                    }
                    tag_end += 1;
                }
                let open_tag = &self.data[open_start..tag_end];
                self.pos = open_end + 1;
                if !is_self_closing && open_tag == tag {
                    depth += 1;
                }
            } else {
                self.pos += 1;
            }
        }
    }
}

fn parse_hex_or_dec(s: &str) -> Result<u64, String> {
    let s = s.trim();
    if s.is_empty() {
        return Ok(0);
    }
    if s.starts_with("0x") || s.starts_with("0X") {
        u64::from_str_radix(&s[2..], 16)
            .map_err(|e| format!("Invalid hex: {} - {}", s, e))
    } else if s.starts_with("0b") || s.starts_with("0B") {
        u64::from_str_radix(&s[2..], 2)
            .map_err(|e| format!("Invalid binary: {} - {}", s, e))
    } else {
        s.parse::<u64>()
            .map_err(|e| format!("Invalid decimal: {} - {}", s, e))
    }
}

fn parse_bit_range(s: &str) -> Option<(u32, u32)> {
    // Format: [msb:lsb]
    let s = s.trim().trim_start_matches('[').trim_end_matches(']');
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len() == 2 {
        let msb = parts[0].trim().parse::<u32>().ok()?;
        let lsb = parts[1].trim().parse::<u32>().ok()?;
        Some((msb, lsb))
    } else {
        None
    }
}

fn parse_dim_index(s: &str) -> Vec<String> {
    let s = s.trim();
    // Could be: "0-3" or "A,B,C,D" or "0,1,2,3"
    if s.contains(',') {
        s.split(',').map(|x| x.trim().to_string()).collect()
    } else if s.contains('-') {
        let parts: Vec<&str> = s.split('-').collect();
        if parts.len() == 2 {
            if let (Ok(start), Ok(end)) = (parts[0].trim().parse::<u32>(), parts[1].trim().parse::<u32>()) {
                return (start..=end).map(|n| n.to_string()).collect();
            }
        }
        vec![s.to_string()]
    } else {
        vec![s.to_string()]
    }
}

