// Utility functions for code generation

/// Format a hex value with underscore separators (groups of 4 from right)
pub fn format_hex(value: u64, bits: u32) -> String {
    // Format as hex with underscore every 4 digits from the right
    let hex = format!("{:x}", value);

    // Add underscores every 4 digits from right
    let mut result = String::new();
    let len = hex.len();
    for (i, c) in hex.chars().enumerate() {
        if i > 0 && (len - i) % 4 == 0 {
            result.push('_');
        }
        result.push(c);
    }

    format!("0x{}", result)
}

/// Format a hex value with proper type suffix
pub fn format_hex_typed(value: u64, bits: u32) -> String {
    let hex_str = format_hex(value, bits);
    let type_str = match bits {
        8 => "u8",
        16 => "u16",
        32 => "u32",
        64 => "u64",
        _ => "u32",
    };
    format!("{} : {} = {} ;", "const RESET_VALUE", type_str, hex_str)
}

/// Get the Rust integer type for a given bit width
pub fn rust_type(bits: u32) -> &'static str {
    match bits {
        8 => "u8",
        16 => "u16",
        32 => "u32",
        64 => "u64",
        _ => "u32",
    }
}

/// Get mask for field bits
pub fn field_mask(width: u32) -> u64 {
    if width >= 64 { u64::MAX } else { (1u64 << width) - 1 }
}

/// Convert a name to snake_case for Rust identifiers
pub fn to_snake_case(s: &str) -> String {
    crate::config::to_snake_case(s)
}

/// Convert a name to PascalCase for Rust types
pub fn to_pascal_case(s: &str) -> String {
    crate::config::to_pascal_case(s)
}

/// Escape a string for use in a doc attribute
pub fn escape_doc(s: &str) -> String {
    s.replace('\\', "\\\\")
     .replace('"', "\\\"")
}

/// Format address offset as hex
pub fn format_offset(offset: u64) -> String {
    format!("0x{:02x}", offset)
}

/// Format a base address for use in generated code
pub fn format_base_address(addr: u64) -> String {
    format_hex(addr, 32)
}

/// Check if a string needs to be a raw identifier (r#keyword)
pub fn needs_raw_ident(s: &str) -> bool {
    matches!(s, 
        "abstract" | "as" | "async" | "await" | "become" | "box" | "break" |
        "const" | "continue" | "crate" | "do" | "dyn" | "else" | "enum" |
        "extern" | "false" | "final" | "fn" | "for" | "if" | "impl" | "in" |
        "let" | "loop" | "macro" | "match" | "mod" | "move" | "mut" | "override" |
        "priv" | "pub" | "ref" | "return" | "Self" | "self" | "static" | "struct" |
        "super" | "trait" | "true" | "try" | "type" | "typeof" | "unsafe" | "unsized" |
        "use" | "virtual" | "where" | "while" | "yield"
    )
}

/// Sanitize an identifier to be a valid Rust identifier
pub fn sanitize_ident(s: &str) -> String {
    let mut result = String::new();
    let mut first = true;
    for c in s.chars() {
        if first {
            if c.is_alphabetic() || c == '_' {
                result.push(c);
                first = false;
