/// Format a hex value with underscore separators (groups of 4 from right)
pub fn format_hex(value: u64, bits: u32) -> String {
    // Format as hex with underscore every 4 digits from the right
    let hex = format!("{:x}", value);

    // Add underscores every 4 digits from right
    let mut result = String::new();
    let len = hex.len();
    for (i, c) in hex.chars().enumerate() {
        if i > 0 && (len - i) % 4 == 0 {
            result.push('_');
        }
