// Generic module template

/// Get the inline generic module content (for when -g is NOT used)
/// This is the token-stream formatted version
pub fn get_generic_module_inline(atomics: bool, atomics_feature: Option<&str>) -> String {
    let mut s = String::new();

    s.push_str(GENERIC_MOD_START);

    if atomics {
        let atomic_mod = if let Some(feature) = atomics_feature {
            format!("#[cfg (feature = {:?})] ", feature)
        } else {
            String::new()
        };
        s.push_str(&format!("{}{}", atomic_mod, ATOMIC_MOD));
    }

    s.push_str(GENERIC_MOD_END);

    s
}

/// Get the separate generic.rs content (for when -g IS used)
/// This is the rustfmt-formatted version
pub fn get_generic_rs(atomics: bool, atomics_feature: Option<&str>) -> String {
    let mut s = String::new();
    s.push_str(GENERIC_RS_CONTENT);

    if atomics {
        if let Some(feature) = atomics_feature {
            s.push_str(&format!("\n#[cfg(feature = {:?})]\n", feature));
        } else {
            s.push('\n');
        }
        s.push_str(ATOMIC_RS_CONTENT);
    }

    s.push('\n');
