fn render_lib_rs(device: &Device, config: &Config) -> Result<String, String> {
    let mut out = String::new();

    // Crate attributes (inner attributes for lib.rs, outer doc for mod.rs)
    if !config.skip_crate_attributes {
        if !config.make_mod {
            // Inner attributes
            // Add MSP430 abi feature if needed
            if config.target == "Msp430" {
                out.push_str("# ! [feature (abi_msp430_interrupt)] ");
            }

            let device_name = &device.name;
            let doc = format!(
                "Peripheral access API for {} microcontrollers (generated using svd2rust v0.37.1 (e29353d 2026-03-03))\\n\\nYou can find an overview of the generated API [here].\\n\\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\\n\\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\\n[repository]: https://github.com/rust-embedded/svd2rust",
                device_name
            );
            out.push_str(&format!("# ! [doc = {:?}] ", doc));
            out.push_str("# ! [allow (non_camel_case_types)] # ! [allow (non_snake_case)] # ! [no_std] # ! [cfg_attr (docsrs , feature (doc_cfg))]");
            out.push('\n');
        } else {
            // Outer doc for mod.rs
            let device_name = &device.name;
            let doc = format!(
                "Peripheral access API for {} microcontrollers (generated using svd2rust v0.37.1 (e29353d 2026-03-03))\\n\\nYou can find an overview of the generated API [here].\\n\\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\\n\\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\\n[repository]: https://github.com/rust-embedded/svd2rust",
                device_name
            );
            out.push_str(&format!("# [doc = {:?}]", doc));
            out.push('\n');
        }
    }

    // use generic::*
    if config.skip_crate_attributes {
        out.push_str("# [allow (unused_imports)] use generic :: * ;\n");
    } else {
        out.push_str("#[allow (unused_imports)] use generic :: * ;\n");
    }

    // Generic module (inline or declaration)
    if config.generic_mod {
        out.push_str("#[doc = \"Common register and bit access and modify traits\"] pub mod generic ;\n");
    } else {
        out.push_str(&generic::get_generic_module_inline(
            config.atomics,
            config.atomics_feature.as_deref(),
        ));
    }

    // Render interrupts section
    render_interrupts_section(&mut out, device, config)?;

    // Render peripherals
    for peripheral in &device.peripherals {
        render_peripheral_top(&mut out, peripheral, device, config)?;
    }

    // Render Peripherals struct
    render_peripherals_struct(&mut out, device, config)?;

    Ok(out)
}

fn render_interrupts_section(out: &mut String, device: &Device, config: &Config) -> Result<(), String> {
    log_debug("svd2rust::generate::device", "Rendering interrupts");

    // Collect all interrupts across all peripherals
    let mut all_interrupts: Vec<&Interrupt> = Vec::new();
    let mut seen_names = std::collections::HashSet::new();

    for p in &device.peripherals {
        for irq in &p.interrupts {
            if seen_names.insert(irq.name.clone()) {
                all_interrupts.push(irq);
            }
        }
    }

    // Sort by value
    all_interrupts.sort_by_key(|i| i.value);

    match config.target.as_str() {
        "CortexM" => render_cortexm_interrupts(out, &all_interrupts, config),
        "Riscv" => render_riscv_interrupts(out, &all_interrupts, device, config),
        "Msp430" => render_msp430_interrupts(out, &all_interrupts, config),
        "XtensaLx" => render_xtensalx_interrupts(out, &all_interrupts, config),
        "Mips" | "None" => render_none_interrupts(out, &all_interrupts, config),
        _ => render_cortexm_interrupts(out, &all_interrupts, config),
    }
}

fn render_cortexm_interrupts(out: &mut String, interrupts: &[&Interrupt], config: &Config) -> Result<(), String> {
    // extern "C" block for interrupt handlers
    if !interrupts.is_empty() {
        out.push_str("#[cfg (feature = \"rt\")] extern \"C\" {");
        for irq in interrupts {
            let irq_name = apply_ident_format(config, "interrupt", &irq.name);
            if config.feature_peripheral {
                // Find which peripheral this interrupt belongs to
                // For simplicity, use lowercase peripheral name as feature
                out.push_str(&format!("\n#[cfg (feature = {:?})] fn {} () ;", 
                    irq_name.to_lowercase(), irq_name));
            } else {
                out.push_str(&format!(" fn {} () ;", irq_name));
            }
        }
        if config.feature_peripheral && !interrupts.is_empty() {
            out.push('\n');
        } else {
            out.push(' ');
        }
        out.push_str("}\n");
    } else {
        out.push_str("#[cfg (feature = \"rt\")] extern \"C\" { }\n");
    }

    // Vector union type
    out.push_str("#[doc (hidden)]\n");
    out.push_str("#[repr (C)] pub union Vector { _handler : unsafe extern \"C\" fn () , _reserved : u32 , }\n");

    // Interrupt table
    out.push_str("#[cfg (feature = \"rt\")]\n");
    out.push_str("#[doc (hidden)]\n");
    out.push_str("#[link_section = \".vector_table.interrupts\"]\n");

    if interrupts.is_empty() {
        out.push_str("#[no_mangle] pub static __INTERRUPTS : [Vector ; 0] = [] ;\n");
    } else {
        let max_irq = interrupts.iter().map(|i| i.value).max().unwrap_or(0);
        let count = max_irq + 1;

        out.push_str(&format!("#[no_mangle] pub static __INTERRUPTS : [Vector ; {}] = [", count));

        let mut irq_map: HashMap<u32, &Interrupt> = HashMap::new();
        for irq in interrupts {
            irq_map.insert(irq.value, irq);
        }

        for i in 0..count {
            if let Some(irq) = irq_map.get(&i) {
                let irq_name = apply_ident_format(config, "interrupt", &irq.name);
                if config.feature_peripheral {
                    let feat = irq_name.to_lowercase();
                    out.push_str(&format!("\n#[cfg (not (all (feature = {:?} ,)))] Vector {{ _reserved : 0 }} ,", feat));
                    out.push_str(&format!("\n#[cfg (feature = {:?})] Vector {{ _handler : {} }} ,", feat, irq_name));
                } else {
                    out.push_str(&format!("Vector {{ _handler : {} }} ,", irq_name));
                }
            } else {
                out.push_str("Vector { _reserved : 0 } ,");
            }
        }
        out.push_str("] ;\n");
    }

    // Interrupt enum
    out.push_str("#[doc = r\"Enumeration of all the interrupts.\"]\n");

    if interrupts.is_empty() {
        out.push_str("#[derive (Copy , Clone , Debug , PartialEq , Eq)] pub enum Interrupt { }");
        out.push_str(" unsafe impl cortex_m :: interrupt :: InterruptNumber for Interrupt {\n");
        out.push_str("#[inline (always)] fn number (self) -> u16 { match self { } } }\n");
    } else {
        out.push_str("#[derive (Copy , Clone , Debug , PartialEq , Eq)]\n");
        out.push_str("#[repr (u16)] pub enum Interrupt {\n");
        for irq in interrupts {
            let irq_name = apply_ident_format(config, "interrupt", &irq.name);
            let desc = irq.description.as_deref().unwrap_or("");
            if config.feature_peripheral {
                let feat = irq_name.to_lowercase();
                out.push_str(&format!("#[cfg (feature = {:?})] ", feat));
            }
            out.push_str(&format!("#[doc = \"{} - {}\"] {} = {} ,\n", 
                irq.value, escape_doc(desc), irq_name, irq.value));
        }

        if config.reexport_interrupt {
            out.push_str("} pub use self :: interrupt :: Interrupt ;\n");
        } else {
            out.push_str("} unsafe impl cortex_m :: interrupt :: InterruptNumber for Interrupt {\n");
            out.push_str("#[inline (always)] fn number (self) -> u16 { self as u16 } }\n");
        }
    }

    Ok(())
}

fn render_riscv_interrupts(out: &mut String, interrupts: &[&Interrupt], device: &Device, config: &Config) -> Result<(), String> {
    // Check if there's a settings file with RISC-V config
    if config.settings.riscv_config.is_none() {
        log_warn("svd2rust::generate::device", "No settings file provided for RISC-V target. Using legacy interrupts rendering");
        log_warn("svd2rust::generate::device", "Please, consider migrating your PAC to riscv 0.12.0 or later");
    }

    // Vector union type (different for RISC-V)
    out.push_str("#[doc (hidden)]\n");
    out.push_str("#[repr (C)] pub union Vector { pub _handler : unsafe extern \"C\" fn () , pub _reserved : usize , }\n");

    // extern "C" block for interrupt handlers
    if !interrupts.is_empty() {
        out.push_str("#[cfg (feature = \"rt\")] extern \"C\" {");
        for irq in interrupts {
            let irq_name = apply_ident_format(config, "interrupt", &irq.name);
            out.push_str(&format!(" fn {} () ;", irq_name));
        }
        out.push_str(" }\n");
    }

    // External interrupts table
    if interrupts.is_empty() {
        out.push_str("#[no_mangle] pub static __EXTERNAL_INTERRUPTS : [Vector ; 0] = [] ;\n");
    } else {
        let max_irq = interrupts.iter().map(|i| i.value).max().unwrap_or(0);
        let count = max_irq + 1;

        out.push_str(&format!("#[no_mangle] pub static __EXTERNAL_INTERRUPTS : [Vector ; {}] = [", count));

        let mut irq_map: HashMap<u32, &Interrupt> = HashMap::new();
        for irq in interrupts {
            irq_map.insert(irq.value, irq);
        }

        for i in 0..count {
            if let Some(irq) = irq_map.get(&i) {
                let irq_name = apply_ident_format(config, "interrupt", &irq.name);
                out.push_str(&format!("Vector {{ _handler : {} }} ,", irq_name));
            } else {
                out.push_str("Vector { _reserved : 0 } ,");
