    out.push_str("#[doc = r\"\"]\n");
    out.push_str("#[doc = r\" # Example\"]\n");
    out.push_str("#[doc = r\"\"]\n");
    out.push_str("#[doc = r\" ``` ignore\"]\n");
    out.push_str("#[doc = r\" interrupt!(TIM2, periodic);\"]\n");
