            let irq_name = apply_ident_format(config, "interrupt", &irq.name);
            let desc = irq.description.as_deref().unwrap_or("");
            out.push_str(&format!("#[doc = \"{} - {}\"] {} = {} ,\n",
                irq.value, escape_doc(desc), irq_name, irq.value));
        }
        out.push_str("} unsafe impl msp430 :: abi :: Interrupt for Interrupt {\n");
        out.push_str("#[inline (always)] fn nr (& self) -> usize { * self as usize } }\n");
    }

    Ok(())
}

fn render_xtensalx_interrupts(out: &mut String, interrupts: &[&Interrupt], config: &Config) -> Result<(), String> {
    // XtensaLx uses a different interrupt mechanism
    // Similar to Cortex-M but different
    render_cortexm_interrupts(out, interrupts, config)
}

fn render_none_interrupts(out: &mut String, interrupts: &[&Interrupt], config: &Config) -> Result<(), String> {
    // For "none" target, just output a simple enum without arch-specific stuff
    if !interrupts.is_empty() {
        out.push_str("#[doc = r\"Enumeration of all the interrupts.\"]\n");
        out.push_str("#[derive (Copy , Clone , Debug , PartialEq , Eq)]\n");
        out.push_str("#[repr (u16)] pub enum Interrupt {\n");
        for irq in interrupts {
            let irq_name = apply_ident_format(config, "interrupt", &irq.name);
            let desc = irq.description.as_deref().unwrap_or("");
            out.push_str(&format!("#[doc = \"{} - {}\"] {} = {} ,\n",
                irq.value, escape_doc(desc), irq_name, irq.value));
        }
        out.push_str("}\n");
    }

    Ok(())
}

fn render_peripheral_top(out: &mut String, peripheral: &Peripheral, device: &Device, config: &Config) -> Result<(), String> {
    log_debug("svd2rust::generate::device", &format!("Rendering peripheral {}", peripheral.name));

    let per_name = apply_ident_format(config, "peripheral", &peripheral.name);
    let per_spec = apply_ident_format(config, "peripheral_spec", &peripheral.name);
    let per_mod = apply_ident_format(config, "peripheral_mod", &peripheral.name);
    let per_singleton = apply_ident_format(config, "peripheral_singleton", &peripheral.name);

    let desc = peripheral.description.as_deref().unwrap_or(&peripheral.name);
    let base_addr = format_hex(peripheral.base_address, 64);

    // Check feature flag
    let feat_prefix = if config.feature_peripheral {
        let feat_name = apply_ident_format(config, "peripheral_feature", &peripheral.name);
        format!("#[cfg (feature = {:?})] ", feat_name)
    } else if config.feature_group {
        if let Some(ref group) = peripheral.group_name {
            let feat_name = apply_ident_format(config, "peripheral_feature", group);
            format!("#[cfg (feature = {:?})] ", feat_name)
        } else {
            String::new()
        }
    } else {
        String::new()
    };

    if let Some(ref derived) = peripheral.derived_from {
        // Derived peripheral
        let derived_mod = apply_ident_format(config, "peripheral_mod", derived);
        let derived_spec = apply_ident_format(config, "peripheral_spec", derived);

        out.push_str(&format!("#[doc = {:?}] {}pub type {} = crate :: Periph < {}Spec > ;", 
            desc, feat_prefix, per_name, per_spec));
        out.push_str(&format!(" {}pub struct {}Spec ; impl crate :: PeripheralSpec for {}Spec {{ type RB = {} :: RegisterBlock ; const ADDRESS : usize = {} ; const NAME : & 'static str = {:?} ; }}\n",
            feat_prefix, per_spec, per_spec, derived_mod, base_addr, per_name));
        out.push_str(&format!("#[doc = {:?}] {}pub use self :: {} as {} ;\n",
            desc, feat_prefix, derived_mod, per_mod));
    } else {
        // Regular peripheral
        out.push_str(&format!("#[doc = {:?}] {}pub type {} = crate :: Periph < {}Spec > ;", 
            desc, feat_prefix, per_name, per_spec));
        out.push_str(&format!(" {}pub struct {}Spec ; impl crate :: PeripheralSpec for {}Spec {{ type RB = {} :: RegisterBlock ; const ADDRESS : usize = {} ; const NAME : & 'static str = {:?} ; }}\n",
            feat_prefix, per_spec, per_spec, per_mod, base_addr, per_name));

        // Peripheral module
        out.push_str(&format!("#[doc = {:?}] {}pub mod {} {{\n", desc, feat_prefix, per_mod));

        per_gen::render_peripheral(out, peripheral, device, config)?;

        out.push_str("}\n");
    }

    Ok(())
}

fn render_peripherals_struct(out: &mut String, device: &Device, config: &Config) -> Result<(), String> {
    out.push_str("#[no_mangle] static mut DEVICE_PERIPHERALS : bool = false ;\n");
    out.push_str("#[doc = r\" All the peripherals.\"]\n");
    out.push_str("#[allow (non_snake_case)] pub struct Peripherals {\n");

    for p in &device.peripherals {
        let per_name = apply_ident_format(config, "peripheral", &p.name);
        let per_singleton = apply_ident_format(config, "peripheral_singleton", &p.name);
        let desc = p.description.as_deref().unwrap_or(&p.name);

        let feat_prefix = if config.feature_peripheral {
            let feat_name = apply_ident_format(config, "peripheral_feature", &p.name);
            format!("#[cfg (feature = {:?})] ", feat_name)
        } else if config.feature_group {
            if let Some(ref group) = p.group_name {
                let feat_name = apply_ident_format(config, "peripheral_feature", group);
                format!("#[cfg (feature = {:?})] ", feat_name)
            } else {
                String::new()
            }
        } else {
            String::new()
        };

        out.push_str(&format!("#[doc = {:?}] {}pub {} : {} , ", 
            p.name.as_str(), feat_prefix, per_singleton, per_name));
    }

    out.push_str("} impl Peripherals {\n");
    out.push_str("#[doc = r\" Returns all the peripherals *once*.\"]\n");
    out.push_str("#[cfg (feature = \"critical-section\")]\n");
    out.push_str("#[inline] pub fn take () -> Option < Self > { critical_section :: with (| _ | { if unsafe { DEVICE_PERIPHERALS } { return None } Some (unsafe { Peripherals :: steal () }) }) }\n");
    out.push_str("#[doc = r\" Unchecked version of `Peripherals::take`.\"]\n");
    out.push_str("#[doc = r\"\"]\n");
    out.push_str("#[doc = r\" # Safety\"]\n");
    out.push_str("#[doc = r\"\"]\n");
    out.push_str("#[doc = r\" Each of the returned peripherals must be used at most once.\"]\n");
    out.push_str("#[inline] pub unsafe fn steal () -> Self { DEVICE_PERIPHERALS = true ; Peripherals { ");

    for p in &device.peripherals {
        let per_singleton = apply_ident_format(config, "peripheral_singleton", &p.name);
        let per_name = apply_ident_format(config, "peripheral", &p.name);

        let feat_prefix = if config.feature_peripheral {
            let feat_name = apply_ident_format(config, "peripheral_feature", &p.name);
            format!("#[cfg (feature = {:?})] ", feat_name)
        } else if config.feature_group {
            if let Some(ref group) = p.group_name {
                let feat_name = apply_ident_format(config, "peripheral_feature", group);
                format!("#[cfg (feature = {:?})] ", feat_name)
            } else {
                String::new()
            }
        } else {
            String::new()
        };

        out.push_str(&format!("{}{} : {} :: steal () , ",
            feat_prefix, per_singleton, per_name));
    }

    out.push_str("} } }\n");

    Ok(())
}

fn render_build_rs() -> String {
    // The build.rs file
    r##"# ! [doc = r" Builder file for Peripheral access crate generated by svd2rust tool"] use std :: env ; use std :: fs :: File ; use std :: io :: Write ; use std :: path :: PathBuf ; fn main () { if env :: var_os ("CARGO_FEATURE_RT") . is_some () { let out = & PathBuf :: from (env :: var_os ("OUT_DIR") . unwrap ()) ; File :: create (out . join ("device.x")) . unwrap () . write_all (include_bytes ! ("device.x")) . unwrap () ; println ! ("cargo:rustc-link-search={}" , out . display ()) ; println ! ("cargo:rerun-if-changed=device.x") ; } println ! ("cargo:rerun-if-changed=build.rs") ; }"##.to_string() + "\n"
}

fn render_device_x(device: &Device, config: &Config) -> String {
    // device.x contains the memory.x linker script
    // For most targets it's empty or contains interrupt table
    match config.target.as_str() {
        "CortexM" => {
            // Check if there are any interrupts
            let has_interrupts = device.peripherals.iter().any(|p| !p.interrupts.is_empty());
            if has_interrupts {
                // Count total interrupts
                let mut max_irq = 0u32;
                for p in &device.peripherals {
                    for irq in &p.interrupts {
                        if irq.value > max_irq {
                            max_irq = irq.value;
                        }
                    }
                }
                format!("PROVIDE(DefaultHandler = DefaultHandler_);\n")
            } else {
                "\n".to_string()
            }
        },
        _ => "\n".to_string(),
    }
}

pub fn apply_ident_format(config: &Config, ident_type: &str, name: &str) -> String {
    if let Some(fmt) = config.ident_formats.get(ident_type) {
        let case = fmt.case.as_deref();
        let cased = match case {
            Some("Pascal") => crate::config::to_pascal_case(name),
            Some("Snake") => crate::config::to_snake_case(name),
            Some("Constant") => crate::config::to_constant_case(name),
            _ => name.to_string(),
        };
        format!("{}{}{}", fmt.prefix, cased, fmt.suffix)
    } else {
        name.to_string()
    }
}

