    let access_str = match (&r.access, is_readable, is_writable) {
        (_, true, true) => "rw",
        (_, true, false) => "r",
        (_, false, true) => "w",
        _ => "rw",
    };

    let desc = r.description.as_deref().unwrap_or("");

