fn build_accessor_doc(reg_name: &str, reg_mod: &str, desc: &str, readable: bool, writable: bool, has_fields: bool) -> String {
    let access_str = match (readable, writable) {
        (true, true) => "rw",
        (true, false) => "r",
        (false, true) => "w",
        _ => "rw",
    };

    let mut doc = format!("{} ({}) register accessor: {}", reg_name, access_str, desc);
    doc.push_str("\\n\\n");

    if readable {
        if writable {
            doc.push_str(&format!(
                "You can [`read`](crate::Reg::read) this register and get [`{}::R`]. ",
                reg_mod
            ));
        } else {
            doc.push_str(&format!(
                "You can [`read`](crate::Reg::read) this register and get [`{}::R`].",
                reg_mod
            ));
        }
    }

    if writable {
        if !readable {
            doc.push_str(&format!(
                "You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`]. ",
                reg_mod
            ));
        } else {
            doc.push_str(&format!(
                "You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`]. ",
                reg_mod
            ));
            doc.push_str("You can also [`modify`](crate::Reg::modify) this register. ");
        }
    }

    if readable || writable {
        doc.push_str("See [API](https://docs.rs/svd2rust/#read--modify--write-api).");
    }

    if has_fields {
        doc.push_str(&format!("\\n\\nFor information about available fields see [`mod@{}`] module", reg_mod));
    }

    doc
}

fn build_register_spec_doc(reg_name: &str, reg_mod: &str, desc: &str, readable: bool, writable: bool) -> String {
    let mut doc = format!("{}\\n\\n", desc);

    if readable && writable {
        doc.push_str(&format!(
            "You can [`read`](crate::Reg::read) this register and get [`{}::R`](R). You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`](W). You can also [`modify`](crate::Reg::modify) this register. See [API](https://docs.rs/svd2rust/#read--modify--write-api).",
            reg_mod, reg_mod
        ));
    } else if readable {
        doc.push_str(&format!(
            "You can [`read`](crate::Reg::read) this register and get [`{}::R`](R). See [API](https://docs.rs/svd2rust/#read--modify--write-api).",
            reg_mod
        ));
    } else if writable {
        doc.push_str(&format!(
            "You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`](W). See [API](https://docs.rs/svd2rust/#read--modify--write-api).",
            reg_mod
        ));
    }

    doc
}

fn calculate_zero_bitmap(fields: &[Field], reg_size: u32) -> u64 {
    // Fields with modifiedWriteValues = zeroToSet/zeroToClear/zeroToToggle
    let mut bitmap = 0u64;
    for f in fields {
        match &f.modified_write_values {
            Some(ModifiedWriteValues::ZeroToSet) | 
            Some(ModifiedWriteValues::ZeroToClear) |
            Some(ModifiedWriteValues::ZeroToToggle) => {
                let mask = field_mask(f.bit_width) << f.bit_offset;
                bitmap |= mask;
            },
            _ => {}
        }
    }
    bitmap
}

fn calculate_one_bitmap(fields: &[Field], reg_size: u32, reg_mwv: &Option<ModifiedWriteValues>) -> u64 {
    // Fields with modifiedWriteValues = oneToClear/oneToSet/oneToToggle
    let mut bitmap = 0u64;
    for f in fields {
        let mwv = f.modified_write_values.as_ref().or(reg_mwv.as_ref());
        match mwv {
            Some(ModifiedWriteValues::OneToClear) |
            Some(ModifiedWriteValues::OneToSet) |
            Some(ModifiedWriteValues::OneToToggle) => {
                let mask = field_mask(f.bit_width) << f.bit_offset;
                bitmap |= mask;
            },
            _ => {}
        }
    }
    bitmap
}

fn render_fields(
    out: &mut String,
    fields: &[Field],
    reg_name: &str,
    reg_mod: &str,
    is_readable: bool,
    is_writable: bool,
    reg_size: u32,
    config: &Config,
) -> Result<(), String> {
    use crate::svd::{EnumeratedValues, EnumeratedValue, EnumValue};

    // Sort fields by bit offset for consistent output
    let mut sorted_fields: Vec<&Field> = fields.iter().collect();
    sorted_fields.sort_by_key(|f| f.bit_offset);

    // First, render field type aliases
    for field in &sorted_fields {
        let field_name = apply_ident_format(config, "field_accessor", &field.name);
        let field_reader = apply_ident_format(config, "field_reader", &field.name);
        let field_writer = apply_ident_format(config, "field_writer", &field.name);

        let desc = field.description.as_deref().unwrap_or("");
        let is_bit = field.bit_width == 1;

        // Check if field has enumerated values
        let has_enum = !field.enumerated_values.is_empty();

        // Get enum name for this field
        let enum_name = if has_enum {
            let ev = &field.enumerated_values[0];
            let name = if let Some(ref n) = ev.name {
                if !n.is_empty() && !config.field_names_for_enums {
                    n.clone()
                } else {
                    field.name.clone()
                }
            } else {
                field.name.clone()
            };
            Some(apply_ident_format(config, "enum_name", &name))
        } else {
            None
        };

        let field_eff_readable = is_readable && field.access.as_ref().map_or(true, |a| a.is_readable());
        let field_eff_writable = is_writable && field.access.as_ref().map_or(true, |a| a.is_writable());

        if field_eff_readable {
            if is_bit {
                if let Some(ref ename) = enum_name {
                    out.push_str(&format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: BitReader < {} > ;\n",
                        field.name, desc, field_reader, ename));
                } else {
                    out.push_str(&format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: BitReader ;\n",
                        field.name, desc, field_reader));
                }
            } else {
                if let Some(ref ename) = enum_name {
                    out.push_str(&format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: FieldReader < {} > ;\n",
                        field.name, desc, field_reader, ename));
                } else {
                    out.push_str(&format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: FieldReader ;\n",
                        field.name, desc, field_reader));
                }
            }
        }

        if field_eff_writable {
            // Determine writer type based on modifiedWriteValues
            let writer_type = get_bit_writer_type(&field.modified_write_values);

            if is_bit {
                if let Some(ref ename) = enum_name {
                    out.push_str(&format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: {} < 'a , REG , {} > ;\n",
                        field.name, desc, field_writer, writer_type, ename));
                } else {
                    out.push_str(&format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: {} < 'a , REG > ;\n",
                        field.name, desc, field_writer, writer_type));
                }
            } else {
                if let Some(ref ename) = enum_name {
                    out.push_str(&format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: FieldWriter < 'a , REG , {} , {} > ;\n",
                        field.name, desc, field_writer, field.bit_width, ename));
                } else {
                    out.push_str(&format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: FieldWriter < 'a , REG , {} > ;\n",
                        field.name, desc, field_writer, field.bit_width));
                }
            }
        }

        // Render enum if present
        if has_enum {
            render_enum(out, &field.enumerated_values[0], &field.name, field.bit_width, field.reset_value_for_field(), config)?;
        }
    }

    // impl R
    if is_readable {
        let has_readable_fields = sorted_fields.iter().any(|f| 
            f.access.as_ref().map_or(true, |a| a.is_readable()));

        if has_readable_fields || !sorted_fields.is_empty() {
            // Check if we need Debug impl
            let needs_debug_impl = if config.impl_debug {
                true
            } else {
                false
            };

            out.push_str("impl R {\n");

            for field in &sorted_fields {
                let field_eff_readable = field.access.as_ref().map_or(true, |a| a.is_readable());
                if !field_eff_readable { continue; }

                let field_accessor = apply_ident_format(config, "field_accessor", &field.name);
                let field_reader = apply_ident_format(config, "field_reader", &field.name);
                let desc = field.description.as_deref().unwrap_or("");
                let is_bit = field.bit_width == 1;

                let bits_desc = if is_bit {
                    format!("Bit {} - {}", field.bit_offset, desc)
                } else {
                    format!("Bits {}:{} - {}", field.bit_offset, field.bit_offset + field.bit_width - 1, desc)
                };

                out.push_str(&format!("#[doc = {:?}]\n", bits_desc));
                out.push_str(&format!("#[inline (always)] pub fn {} (& self) -> {} {{", 
                    field_accessor, field_reader));

                if is_bit {
                    out.push_str(&format!(" {} :: new ((self . bits & {}) != 0) }}", 
                        field_reader, 1u64 << field.bit_offset));
                } else {
                    let shift = field.bit_offset;
                    let mask = field_mask(field.bit_width);
                    let cast_type = rust_type(reg_size);
                    let result_type = rust_type_for_field_width(field.bit_width);

                    if shift == 0 {
                        out.push_str(&format!(" {} :: new ((self . bits & {}) as {}) }}", 
                            field_reader, mask, result_type));
                    } else {
                        out.push_str(&format!(" {} :: new (((self . bits >> {}) & {}) as {}) }}", 
                            field_reader, shift, mask, result_type));
                    }
                }
                out.push('\n');
            }

            // Debug impl
            if config.impl_debug {
                out.push_str(&format!("}} impl core :: fmt :: Debug for R {{ fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result {{ f . debug_struct ({:?})", reg_name.to_uppercase()));
                for field in &sorted_fields {
                    let field_eff_readable = field.access.as_ref().map_or(true, |a| a.is_readable());
                    if !field_eff_readable { continue; }
                    let field_accessor = apply_ident_format(config, "field_accessor", &field.name);
                    let field_name_str = field_accessor.clone();
                    out.push_str(&format!(" . field ({:?} , & self . {} ())", field_name_str, field_accessor));
                }
                out.push_str(" . finish () } }");
            } else {
                out.push_str("}");
            }

            out.push_str(" impl W {\n");
        } else {
            out.push_str("impl W {\n");
        }
    } else {
        out.push_str("impl W {\n");
    }

    // impl W
    if is_writable {
        for field in &sorted_fields {
            let field_eff_writable = field.access.as_ref().map_or(true, |a| a.is_writable());
            if !field_eff_writable { continue; }

            let field_accessor = apply_ident_format(config, "field_accessor", &field.name);
            let field_writer = apply_ident_format(config, "field_writer", &field.name);
            let desc = field.description.as_deref().unwrap_or("");
            let is_bit = field.bit_width == 1;

            let bits_desc = if is_bit {
                format!("Bit {} - {}", field.bit_offset, desc)
            } else {
                format!("Bits {}:{} - {}", field.bit_offset, field.bit_offset + field.bit_width - 1, desc)
            };

            out.push_str(&format!("#[doc = {:?}]\n", bits_desc));
            out.push_str(&format!("#[inline (always)] pub fn {} (& mut self) -> {} < '_ , {}Spec > {{ {} :: new (self , {}) }}\n",
                field_accessor, field_writer, reg_name, field_writer, field.bit_offset));
        }
    }

    out.push_str("}\n");

    Ok(())
}

fn render_enum(
    out: &mut String,
    ev: &crate::svd::EnumeratedValues,
    field_name: &str,
    bit_width: u32,
    reset_val: Option<u64>,
    config: &Config,
) -> Result<(), String> {
    use crate::svd::EnumValue;

    let enum_display_name = if let Some(ref n) = ev.name {
        if !n.is_empty() && !config.field_names_for_enums {
            n.clone()
        } else {
            field_name.to_string()
        }
    } else {
        field_name.to_string()
    };

    let enum_name = apply_ident_format(config, "enum_name", &enum_display_name);

    let desc = format!("{}\\n\\nValue on reset: {}", field_name, reset_val.unwrap_or(0));

    out.push_str(&format!("#[doc = {:?}]\n", desc));
    out.push_str("#[derive (Clone , Copy , Debug , PartialEq , Eq)]\n");

    // Determine the repr type
    let repr_type = rust_type_for_field_width(bit_width);
    out.push_str(&format!("#[repr ({})] pub enum {} {{\n", repr_type, enum_name));

    for val in &ev.values {
        if val.is_default { continue; }
        if let Some(ref v) = val.value {
            let v_num = match v {
                EnumValue::Value(n) => *n,
                EnumValue::Default => continue,
            };
            let variant_name = apply_ident_format(config, "enum_value", &val.name);
            let val_desc = val.description.as_deref().unwrap_or("");
            out.push_str(&format!("#[doc = \"{}: {}\"] {} = {} ,\n",
                v_num, escape_doc(val_desc), variant_name, v_num));
        }
    }

    out.push_str(&format!("}} impl From < {} > for {} {{\n", enum_name, repr_type));
    out.push_str(&format!("#[inline (always)] fn from (variant : {}) -> Self {{ variant as _ }}", enum_name));
    out.push_str(&format!("}} impl crate :: FieldSpec for {} {{ type Ux = {} ; }}", enum_name, repr_type));
    out.push_str(&format!(" impl crate :: IsEnum for {} {{ }}\n", enum_name));

    // Reader impl
    let field_reader = apply_ident_format(config, "field_reader", &enum_display_name);
    out.push_str(&format!("impl {} {{\n", field_reader));
    out.push_str("#[doc = \"Get enumerated values variant\"]\n");
    out.push_str(&format!("#[inline (always)] pub const fn variant (& self) -> Option < {} > {{ match self . bits {{", enum_name));

    for val in &ev.values {
        if val.is_default { continue; }
        if let Some(ref v) = val.value {
            let v_num = match v {
                EnumValue::Value(n) => *n,
                EnumValue::Default => continue,
            };
            let variant_name = apply_ident_format(config, "enum_value", &val.name);
            out.push_str(&format!(" {} => Some ({} :: {}) ,", v_num, enum_name, variant_name));
        }
    }
    out.push_str(" _ => None , } }\n");

    for val in &ev.values {
        if val.is_default { continue; }
        if let Some(ref v) = val.value {
            let v_num = match v {
                EnumValue::Value(n) => *n,
                EnumValue::Default => continue,
            };
            let variant_name = apply_ident_format(config, "enum_value", &val.name);
            let accessor_name = apply_ident_format(config, "enum_value_accessor", &val.name);
            let val_desc = val.description.as_deref().unwrap_or("");
            out.push_str(&format!("#[doc = {:?}]\n", val_desc));
            out.push_str(&format!("#[inline (always)] pub fn {} (& self) -> bool {{ * self == {} :: {} }}\n",
                accessor_name, enum_name, variant_name));
        }
    }

    out.push_str("}\n");

    // Writer impl (if field is writable)
    // This is handled by the field_writer type alias, not here
    // But we need to add impl for enum variants
    let field_writer_type = apply_ident_format(config, "field_writer", &enum_display_name);
    out.push_str(&format!("impl < 'a , REG > {} < 'a , REG > where REG : crate :: Writable + crate :: RegisterSpec , REG :: Ux : From < {} > {{\n",
        field_writer_type, repr_type));

    for val in &ev.values {
        if val.is_default { continue; }
        if let Some(ref v) = val.value {
            let v_num = match v {
                EnumValue::Value(n) => *n,
                EnumValue::Default => continue,
            };
            let variant_name = apply_ident_format(config, "enum_value", &val.name);
            let accessor_name = apply_ident_format(config, "enum_value_accessor", &val.name);
            let val_desc = val.description.as_deref().unwrap_or("");
            out.push_str(&format!("#[doc = {:?}]\n", val_desc));
            out.push_str(&format!("#[inline (always)] pub fn {} (self) -> & 'a mut crate :: W < REG > {{ self . variant ({} :: {}) }}\n",
                accessor_name, enum_name, variant_name));
        }
    }

    out.push_str("}\n");

    Ok(())
}

fn get_bit_writer_type(mwv: &Option<ModifiedWriteValues>) -> &'static str {
    match mwv {
        Some(ModifiedWriteValues::OneToClear) => "BitWriter1C",
        Some(ModifiedWriteValues::OneToSet) => "BitWriter1S",
        Some(ModifiedWriteValues::OneToToggle) => "BitWriter1T",
        Some(ModifiedWriteValues::ZeroToClear) => "BitWriter0C",
        Some(ModifiedWriteValues::ZeroToSet) => "BitWriter0S",
        Some(ModifiedWriteValues::ZeroToToggle) => "BitWriter0T",
        _ => "BitWriter",
    }
}

fn rust_type_for_field_width(width: u32) -> &'static str {
    match width {
        1..=8 => "u8",
        9..=16 => "u16",
        17..=32 => "u32",
        _ => "u64",
    }
}

