        let mut s = String::from("Config {\n");
        s.push_str(&format!("        edition: {},\n", self.edition));
        s.push_str(&format!("        target: {},\n", self.target));
        s.push_str(&format!("        atomics: {},\n", self.atomics));
        s.push_str(&format!("        atomics_feature: {:?},\n", self.atomics_feature));
        s.push_str(&format!("        generic_mod: {},\n", self.generic_mod));
