        s.push_str(&format!("        ident_formats_theme: {:?},\n", self.ident_formats_theme));
        s.push_str(&format!("        field_names_for_enums: {},\n", self.field_names_for_enums));
        s.push_str(&format!("        base_address_shift: {},\n", self.base_address_shift));
        s.push_str(&format!("        settings_file: {:?},\n", self.settings_file.as_ref().map(|s| s.as_str())));
        s.push_str("        settings: Settings {\n");
        s.push_str(&format!("            html_url: {:?},\n", self.settings.html_url));
        s.push_str(&format!("            crate_path: {:?},\n", self.settings.crate_path));
        s.push_str("            riscv_config: None,\n");
        s.push_str("        },\n");
        s.push_str("    }");
        s
    }

    pub fn format_ident(&self, ident_type: &str, name: &str) -> String {
        if let Some(fmt) = self.ident_formats.get(ident_type) {
            let cased = match fmt.case.as_deref() {
                Some("Pascal") => to_pascal_case(name),
                Some("Snake") => to_snake_case(name),
                Some("Constant") => to_constant_case(name),
                _ => name.to_string(),
            };
            format!("{}{}{}", fmt.prefix, cased, fmt.suffix)
        } else {
            name.to_string()
        }
    }
}

pub fn to_pascal_case(s: &str) -> String {
    // Split on separators, then for each part: capitalize first alpha, lowercase rest
    let mut parts: Vec<Vec<char>> = Vec::new();
    let mut current: Vec<char> = Vec::new();

    for c in s.chars() {
        if c == '_' || c == '-' {
            if !current.is_empty() {
                parts.push(current.clone());
                current.clear();
            }
        } else {
            current.push(c);
        }
    }
    if !current.is_empty() {
        parts.push(current);
    }

    if parts.is_empty() {
        return s.to_string();
    }

    let mut result = String::new();
    for part in &parts {
        let mut first_alpha = true;
        for &c in part {
            if c.is_alphabetic() {
                if first_alpha {
                    result.extend(c.to_uppercase());
                    first_alpha = false;
                } else {
                    result.extend(c.to_lowercase());
                }
            } else {
                result.push(c);
            }
        }
    }
    result
}

pub fn to_snake_case(s: &str) -> String {
    // Simple: lowercase everything, keep underscores, convert non-alnum to underscore
    let mut result = String::new();
    for c in s.chars() {
        if c.is_alphanumeric() {
            result.extend(c.to_lowercase());
        } else if c == '_' {
            result.push('_');
        } else {
            result.push('_');
        }
    }
    // Remove consecutive underscores and leading/trailing
    let cleaned: String = result.chars().collect();
    cleaned
}

pub fn to_constant_case(s: &str) -> String {
    // UPPERCASE version of snake_case 
    to_snake_case(s).to_uppercase()
}
