impl Config {
    pub fn apply_toml(&mut self, content: &str) -> Result<(), String> {
        for line in content.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') { continue; }
            if let Some(eq_pos) = line.find('=') {
                let key = line[..eq_pos].trim();
                let value_raw = line[eq_pos+1..].trim();
                let value = value_raw.trim_matches('"').trim_matches('\'');
                match key {
                    "target" => {
                        match value {
                            "cortex-m" => self.target = "CortexM".to_string(),
                            "msp430" => self.target = "Msp430".to_string(),
                            "riscv" => self.target = "Riscv".to_string(),
                            "xtensa-lx" => self.target = "XtensaLx".to_string(),
                            "mips" => self.target = "Mips".to_string(),
                            "none" => self.target = "None".to_string(),
                            _ => {}
                        }
                    },
                    "atomics" => { if value == "true" { self.atomics = true; } },
                    "generic_mod" => { if value == "true" { self.generic_mod = true; } },
                    "make_mod" => { if value == "true" { self.make_mod = true; } },
                    "strict" => { if value == "true" { self.strict = true; } },
                    "edition" => {
                        match value {
                            "2021" => self.edition = "E2021".to_string(),
                            "2024" => self.edition = "E2024".to_string(),
                            _ => {}
                        }
                    },
                    _ => {}
                }
            }
        }
        Ok(())
    }

    pub fn apply_settings_yaml(&mut self, _content: &str) -> Result<(), String> {
        Ok(())
    }

    pub fn apply_ident_format(&mut self, spec: &str) -> Result<(), String> {
        let parts: Vec<&str> = spec.splitn(4, ':').collect();
        let type_name = parts.get(0).copied().unwrap_or("");
        let prefix = parts.get(1).copied().unwrap_or("");
        let case_str = parts.get(2).copied().unwrap_or("");
        let suffix = parts.get(3).copied().unwrap_or("");

        let case = match case_str {
            "" => None,
            "p" | "pascal" => Some("Pascal"),
            "c" | "constant" => Some("Constant"),
            "s" | "snake" => Some("Snake"),
            other => return Err(format!("Unknown case: {}", other)),
        };

        self.ident_formats.insert(type_name.to_string(), IdentFormat::new(case, prefix, suffix));
        Ok(())
    }

    pub fn apply_theme(&mut self, theme: &str) -> Result<(), String> {
        match theme {
            "new" => {},
            "legacy" => {
                self.ident_formats.insert("enum_write_name".to_string(), IdentFormat::new(Some("Pascal"), "", "W"));
            },
            _ => return Err(format!("Unknown theme: {}", theme)),
        }
        Ok(())
    }

    pub fn debug_display(&self) -> String {
        let mut s = String::from("Config {\n");
        s.push_str(&format!("        edition: {},\n", self.edition));
        s.push_str(&format!("        target: {},\n", self.target));
        s.push_str(&format!("        atomics: {},\n", self.atomics));
        s.push_str(&format!("        atomics_feature: {:?},\n", self.atomics_feature));
        s.push_str(&format!("        generic_mod: {},\n", self.generic_mod));
        s.push_str(&format!("        make_mod: {},\n", self.make_mod));
        s.push_str(&format!("        skip_crate_attributes: {},\n", self.skip_crate_attributes));
        s.push_str(&format!("        ignore_groups: {},\n", self.ignore_groups));
        s.push_str(&format!("        keep_list: {},\n", self.keep_list));
        s.push_str(&format!("        strict: {},\n", self.strict));
        s.push_str(&format!("        feature_group: {},\n", self.feature_group));
        s.push_str(&format!("        feature_peripheral: {},\n", self.feature_peripheral));
        s.push_str(&format!("        max_cluster_size: {},\n", self.max_cluster_size));
        s.push_str(&format!("        impl_debug: {},\n", self.impl_debug));
        s.push_str(&format!("        impl_debug_feature: {:?},\n", self.impl_debug_feature));
        s.push_str(&format!("        impl_defmt: {:?},\n", self.impl_defmt));

        // output_dir as Path-like debug
        match &self.output_dir {
            None => s.push_str("        output_dir: None,\n"),
            Some(p) => s.push_str(&format!("        output_dir: Some(\n            {:?},\n        ),\n", p)),
        }
        match &self.input {
            None => s.push_str("        input: None,\n"),
            Some(p) => s.push_str(&format!("        input: Some(\n            {:?},\n        ),\n", p)),
        }

        let src_type = match self.source_type.as_str() {
            "xml" => "Xml",
            "yaml" => "Yaml",
            "json" => "Json",
            x => x,
        };
        s.push_str(&format!("        source_type: {},\n", src_type));
        s.push_str(&format!("        log_level: {:?},\n", self.log_level));
        s.push_str(&format!("        interrupt_link_section: {:?},\n", self.interrupt_link_section));
        s.push_str(&format!("        reexport_core_peripherals: {},\n", self.reexport_core_peripherals));
        s.push_str(&format!("        reexport_interrupt: {},\n", self.reexport_interrupt));

        s.push_str("        ident_formats: IdentFormats(\n");
        s.push_str("            {\n");
        // HashMap - order is not deterministic, but we'll use sorted for consistent output
        let mut keys: Vec<&String> = self.ident_formats.keys().collect();
        keys.sort();
        for key in &keys {
            let fmt = &self.ident_formats[*key];
            s.push_str(&format!("                {:?}: IdentFormat {{\n", key));
            match fmt.case.as_deref() {
                None => s.push_str("                    case: None,\n"),
                Some("Pascal") => s.push_str("                    case: Some(\n                        Pascal,\n                    ),\n"),
                Some("Snake") => s.push_str("                    case: Some(\n                        Snake,\n                    ),\n"),
                Some("Constant") => s.push_str("                    case: Some(\n                        Constant,\n                    ),\n"),
                Some(other) => s.push_str(&format!("                    case: Some({:?}),\n", other)),
            }
            s.push_str(&format!("                    prefix: {:?},\n", fmt.prefix));
            s.push_str(&format!("                    suffix: {:?},\n", fmt.suffix));
            s.push_str("                },\n");
        }
        s.push_str("            },\n");
        s.push_str("        ),\n");

        s.push_str(&format!("        ident_formats_theme: {:?},\n", self.ident_formats_theme));
        s.push_str(&format!("        field_names_for_enums: {},\n", self.field_names_for_enums));
        s.push_str(&format!("        base_address_shift: {},\n", self.base_address_shift));
        match &self.settings_file {
            None => s.push_str("        settings_file: None,\n"),
            Some(p) => s.push_str(&format!("        settings_file: Some(\n            {:?},\n        ),\n", p)),
        }
        s.push_str("        settings: Settings {\n");
        s.push_str(&format!("            html_url: {:?},\n", self.settings.html_url));
        s.push_str(&format!("            crate_path: {:?},\n", self.settings.crate_path));
        s.push_str("            riscv_config: None,\n");
        s.push_str("        },\n");
        s.push_str("    }");
        s
    }
}

pub fn to_pascal_case(s: &str) -> String {
    let mut parts: Vec<Vec<char>> = Vec::new();
    let mut current: Vec<char> = Vec::new();

    for c in s.chars() {
        if c == '_' || c == '-' {
            if !current.is_empty() {
                parts.push(std::mem::take(&mut current));
            }
        } else {
            current.push(c);
        }
    }
    if !current.is_empty() {
        parts.push(current);
    }

    if parts.is_empty() {
        return s.to_string();
    }

    let mut result = String::new();
    for part in &parts {
        let mut first_alpha = true;
        for &c in part {
            if c.is_alphabetic() {
                if first_alpha {
                    result.extend(c.to_uppercase());
                    first_alpha = false;
                } else {
                    result.extend(c.to_lowercase());
                }
            } else {
                // Digit or other char
                result.push(c);
            }
        }
    }
    result
}

pub fn to_snake_case(s: &str) -> String {
    s.chars().map(|c| {
        if c == '_' || c == '-' {
            '_'
        } else if c.is_alphanumeric() {
            c.to_lowercase().next().unwrap_or(c)
        } else {
            '_'
        }
    }).collect()
}

pub fn to_constant_case(s: &str) -> String {
    to_snake_case(s).to_uppercase()
}
