use crate::config::Config;
use crate::svd::{Device, Peripheral, Register, RegisterOrCluster, Field, Access, ModifiedWriteValues};
use super::register as reg_gen;
use super::device::apply_ident_format;
use crate::log_debug;

pub fn render_peripheral(out: &mut String, peripheral: &Peripheral, device: &Device, config: &Config) -> Result<(), String> {
    log_debug("svd2rust::generate::peripheral", "Checking derivation information");
    log_debug("svd2rust::generate::peripheral", "Pushing cluster & register information into output");

    let registers = &peripheral.registers;

    log_debug("svd2rust::generate::peripheral", 
        &format!("Pushing {} register or cluster blocks into output", registers.len()));
    log_debug("svd2rust::generate::peripheral", 
        "Expanding registers or clusters into Register Block Fields");

    // Generate RegisterBlock
    render_register_block(out, peripheral, device, config)?;

    // Generate register type aliases and modules
    for roc in registers {
        render_register_or_cluster(out, roc, peripheral, device, config)?;
    }

    Ok(())
}

struct RegBlockEntry {
    offset: u64,
    size_bytes: u64,
    field_name: String,
    type_name: String,
    doc: String,
    is_array: bool,
    array_count: u32,
}

fn collect_register_entries(registers: &[RegisterOrCluster], config: &Config) -> Vec<RegBlockEntry> {
    let mut entries = Vec::new();

    for roc in registers {
        match roc {
            RegisterOrCluster::Register(r) => {
                let field_name = apply_ident_format(config, "register_accessor", &r.name);
                let type_name = apply_ident_format(config, "register", &r.name);
                let doc = r.description.as_deref().unwrap_or("").to_string();
                entries.push(RegBlockEntry {
                    offset: r.address_offset,
                    size_bytes: (r.size / 8) as u64,
                    field_name,
                    type_name,
                    doc,
                    is_array: false,
                    array_count: 1,
                });
            },
            RegisterOrCluster::RegisterArray(ra) => {
                let base_name = ra.name.trim_end_matches("%s").trim_end_matches('_');
                let field_name = apply_ident_format(config, "register_accessor", base_name);
                let type_name = apply_ident_format(config, "register", base_name);
                let doc = ra.description.as_deref().unwrap_or("").to_string();
                // Array takes up dim * dim_increment bytes
                entries.push(RegBlockEntry {
                    offset: ra.address_offset,
                    size_bytes: (ra.dim_increment as u64) * (ra.dim as u64),
                    field_name,
                    type_name,
                    doc,
                    is_array: true,
                    array_count: ra.dim,
                });
            },
            RegisterOrCluster::Cluster(c) => {
                // Handle cluster as a sub-type
                let field_name = apply_ident_format(config, "cluster_accessor", &c.name);
                let type_name = apply_ident_format(config, "cluster", &c.name);
                let doc = c.description.as_deref().unwrap_or("").to_string();
                // Calculate cluster size
                let size_bytes = calculate_cluster_size(&c.registers, config);
                entries.push(RegBlockEntry {
                    offset: c.address_offset,
                    size_bytes,
                    field_name,
                    type_name,
                    doc,
                    is_array: false,
                    array_count: 1,
                });
            },
            RegisterOrCluster::ClusterArray(ca) => {
                let base_name = ca.name.trim_end_matches("%s").trim_end_matches('_');
                let field_name = apply_ident_format(config, "cluster_accessor", base_name);
                let type_name = apply_ident_format(config, "cluster", base_name);
                let doc = ca.description.as_deref().unwrap_or("").to_string();
                let cluster_size = (ca.dim_increment as u64) * (ca.dim as u64);
                entries.push(RegBlockEntry {
                    offset: ca.address_offset,
                    size_bytes: cluster_size,
                    field_name,
                    type_name,
                    doc,
                    is_array: true,
                    array_count: ca.dim,
                });
            },
        }
    }

    // Sort by offset
    entries.sort_by_key(|e| e.offset);
    entries
}

fn calculate_cluster_size(registers: &[RegisterOrCluster], config: &Config) -> u64 {
    let entries = collect_register_entries(registers, config);
    if entries.is_empty() { return 0; }
    let last = entries.last().unwrap();
    last.offset + last.size_bytes
}

fn render_register_block(out: &mut String, peripheral: &Peripheral, device: &Device, config: &Config) -> Result<(), String> {
    let entries = collect_register_entries(&peripheral.registers, config);

    // Build layout with padding
    struct LayoutItem {
        is_reg: bool,
        name: String,
        type_name: String,
        offset: u64,
        size_bytes: u64,
        doc: String,
        is_array: bool,
        array_count: u32,
    }

    let mut layout: Vec<LayoutItem> = Vec::new();
    let mut current_offset = 0u64;
    let mut pad_idx = 1u32;

    for entry in &entries {
        if entry.offset > current_offset {
            // Need padding
            let pad_size = entry.offset - current_offset;
            layout.push(LayoutItem {
                is_reg: false,
                name: format!("_reserved{}", pad_idx),
                type_name: format!("[u8 ; 0x{:02x}]", pad_size),
                offset: current_offset,
                size_bytes: pad_size,
                doc: String::new(),
                is_array: false,
                array_count: 1,
            });
            pad_idx += 1;
        }

        let item_type = if entry.is_array {
            format!("[{} ; {}]", entry.type_name, entry.array_count)
        } else {
            entry.type_name.clone()
        };

        layout.push(LayoutItem {
            is_reg: true,
            name: entry.field_name.clone(),
            type_name: item_type,
            offset: entry.offset,
            size_bytes: entry.size_bytes,
            doc: entry.doc.clone(),
            is_array: entry.is_array,
            array_count: entry.array_count,
        });

        current_offset = entry.offset + entry.size_bytes;
    }

    // Generate RegisterBlock
    out.push_str("#[repr (C)]\n");

    if config.impl_debug {
        if let Some(ref feature) = config.impl_debug_feature {
            out.push_str(&format!("#[cfg_attr (feature = {:?} , derive (Debug))]\n", feature));
        } else {
            out.push_str("#[derive (Debug)]\n");
        }
    }

    out.push_str("#[doc = \"Register block\"] pub struct RegisterBlock { ");

    for item in &layout {
        if item.is_reg {
            out.push_str(&format!("{} : {} , ", item.name, item.type_name));
        } else {
            // padding
            out.push_str(&format!("{} : {} , ", item.name, item.type_name));
        }
    }

    out.push_str("} impl RegisterBlock {\n");

    // Accessor methods for registers
    for (orig_entry, item) in entries.iter().zip(layout.iter().filter(|i| i.is_reg)) {
        let offset_doc = format!("0x{:02x} - {}", orig_entry.offset, orig_entry.doc);
        out.push_str(&format!("#[doc = {:?}]\n", offset_doc));

        if orig_entry.is_array {
            out.push_str(&format!("#[inline (always)] pub const fn {} (& self , n : usize) -> & {} {{ & self . {} [n] }}\n",
                orig_entry.field_name, orig_entry.type_name, orig_entry.field_name));
        } else {
            out.push_str(&format!("#[inline (always)] pub const fn {} (& self) -> & {} {{ & self . {} }}\n",
                orig_entry.field_name, orig_entry.type_name, orig_entry.field_name));
        }
    }

    out.push_str("}\n");

    Ok(())
}

pub fn render_register_or_cluster(
    out: &mut String, 
    roc: &RegisterOrCluster, 
    peripheral: &Peripheral,
    device: &Device,
    config: &Config
) -> Result<(), String> {
    match roc {
        RegisterOrCluster::Register(r) => {
            reg_gen::render_register(out, r, peripheral, device, config)?;
        },
        RegisterOrCluster::RegisterArray(ra) => {
            reg_gen::render_register_array(out, ra, peripheral, device, config)?;
        },
        RegisterOrCluster::Cluster(c) => {
            render_cluster(out, c, peripheral, device, config)?;
        },
        RegisterOrCluster::ClusterArray(ca) => {
            render_cluster_array(out, ca, peripheral, device, config)?;
        },
    }
    Ok(())
}

fn render_cluster(
    out: &mut String,
    cluster: &crate::svd::Cluster,
    peripheral: &Peripheral,
    device: &Device,
    config: &Config,
) -> Result<(), String> {
    let cl_name = apply_ident_format(config, "cluster", &cluster.name);
    let cl_mod = apply_ident_format(config, "cluster_mod", &cluster.name);

    let desc = cluster.description.as_deref().unwrap_or("");
    out.push_str(&format!("#[doc = {:?}] pub mod {} {{\n", desc, cl_mod));

    // Render sub-registers
    let sub_peripheral = Peripheral {
        name: cluster.name.clone(),
        description: cluster.description.clone(),
        group_name: None,
        base_address: 0,
        derived_from: None,
        registers: cluster.registers.clone(),
        interrupts: vec![],
        address_block: None,
        default_register_size: cluster.default_register_size,
        default_reset_value: cluster.default_reset_value,
        default_reset_mask: cluster.default_reset_mask,
        default_access: cluster.default_access.clone(),
    };

    render_peripheral(out, &sub_peripheral, device, config)?;

    out.push_str("}\n");
    Ok(())
}

fn render_cluster_array(
    out: &mut String,
    ca: &crate::svd::ClusterArray,
    peripheral: &Peripheral,
    device: &Device,
    config: &Config,
) -> Result<(), String> {
    // Similar to cluster but with dim
    let base_name = ca.name.trim_end_matches("%s").trim_end_matches('_');
    let cl_mod = apply_ident_format(config, "cluster_mod", base_name);
    let desc = ca.description.as_deref().unwrap_or("");

    out.push_str(&format!("#[doc = {:?}] pub mod {} {{\n", desc, cl_mod));

    let sub_peripheral = Peripheral {
        name: ca.name.clone(),
        description: ca.description.clone(),
        group_name: None,
        base_address: 0,
        derived_from: None,
        registers: ca.registers.clone(),
        interrupts: vec![],
        address_block: None,
        default_register_size: ca.default_register_size,
        default_reset_value: ca.default_reset_value,
        default_reset_mask: ca.default_reset_mask,
        default_access: ca.default_access.clone(),
    };

    render_peripheral(out, &sub_peripheral, device, config)?;

    out.push_str("}\n");
    Ok(())
}
