fn render_no_fields(out: &mut String, reg_name: &str, reg_spec: &str, is_readable: bool, is_writable: bool, config: &Config) {
    if !is_readable && is_writable {
        // write-only, no fields
        out.push_str(&format!(" impl core :: fmt :: Debug for crate :: generic :: Reg < {} > {{ fn fmt (& self , f : & mut core :: fmt :: Formatter < '_ >) -> core :: fmt :: Result {{ write ! (f , \"(not readable)\") }} }}", reg_spec));
        out.push_str(" impl W { }\n");
    } else if is_readable && !is_writable {
        // read-only, no fields
        out.push_str(" impl core :: fmt :: Debug for R { fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result { write ! (f , \"{}\" , self . bits ()) } }\n");
    } else {
        // read-write, no fields
        out.push_str(" impl core :: fmt :: Debug for R { fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result { write ! (f , \"{}\" , self . bits ()) } }");
        out.push_str(" impl W { }\n");
    }
}

struct FieldTypeOutput {
    lines: Vec<String>,       // Lines before "impl R {"
    has_trailing_close: bool, // Whether the last line ends with "}" (from enum impl)
}

fn render_fields(
    out: &mut String,
    fields: &[Field],
    reg_name: &str,
    reg_spec: &str,
    reg_mod: &str,
    is_readable: bool,
    is_writable: bool,
    reg_size: u32,
    config: &Config,
) -> Result<(), String> {
    // Sort fields by bit offset
    let mut sorted_fields: Vec<&Field> = fields.iter().collect();
    sorted_fields.sort_by_key(|f| f.bit_offset);

    // We need to collect all the field type definitions first
    // The last one gets "impl R {" or relevant impl appended to it

    let mut field_type_parts: Vec<String> = Vec::new();

    for field in &sorted_fields {
        let field_name_orig = &field.name;
        let field_accessor = apply_ident_format(config, "field_accessor", field_name_orig);
        let field_reader_name = apply_ident_format(config, "field_reader", field_name_orig);
        let field_writer_name = apply_ident_format(config, "field_writer", field_name_orig);

        let desc = field.description.as_deref().unwrap_or("");
        let is_bit = field.bit_width == 1;

        let has_enum = !field.enumerated_values.is_empty();

        let field_eff_readable = is_readable && field.access.as_ref().map_or(true, |a| a.is_readable());
        let field_eff_writable = is_writable && field.access.as_ref().map_or(true, |a| a.is_writable());

        // Get enum name 
        let enum_name_opt = if has_enum {
            let ev = &field.enumerated_values[0];
            let raw_name = if let Some(ref n) = ev.name {
                if !n.is_empty() && !config.field_names_for_enums {
                    n.clone()
                } else {
                    field_name_orig.clone()
                }
            } else {
                field_name_orig.clone()
            };
            Some(apply_ident_format(config, "enum_name", &raw_name))
        } else {
            None
        };

        // Field reader type alias
        if field_eff_readable {
            let reader_line = if is_bit {
                if let Some(ref ename) = enum_name_opt {
                    format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: BitReader < {} > ;",
                        field_name_orig, desc, field_reader_name, ename)
                } else {
                    format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: BitReader ;",
                        field_name_orig, desc, field_reader_name)
                }
            } else {
                if let Some(ref ename) = enum_name_opt {
                    format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: FieldReader < {} > ;",
                        field_name_orig, desc, field_reader_name, ename)
                } else {
                    format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: FieldReader ;",
                        field_name_orig, desc, field_reader_name)
                }
            };
            field_type_parts.push(reader_line);
        }

        // Enum definitions and impl
        if has_enum {
            let ev = &field.enumerated_values[0];
            let enum_lines = render_enum_type(ev, field_name_orig, field.bit_width, config)?;
            for line in enum_lines {
                field_type_parts.push(line);
            }
        }

        // Field writer type alias (and possibly enum writer impl)
        if field_eff_writable {
            let writer_type = get_bit_writer_type(&field.modified_write_values);

            let writer_line = if is_bit {
                if let Some(ref ename) = enum_name_opt {
                    format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: {} < 'a , REG , {} > ;",
                        field_name_orig, desc, field_writer_name, writer_type, ename)
                } else {
                    format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: {} < 'a , REG > ;",
                        field_name_orig, desc, field_writer_name, writer_type)
                }
            } else {
                if let Some(ref ename) = enum_name_opt {
                    format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: FieldWriter < 'a , REG , {} , {} > ;",
                        field_name_orig, desc, field_writer_name, field.bit_width, ename)
                } else {
                    format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: FieldWriter < 'a , REG , {} > ;",
                        field_name_orig, desc, field_writer_name, field.bit_width)
                }
            };

            if has_enum {
                // Append enum writer impl to the writer type alias line
                if let Some(ref ename) = enum_name_opt {
                    let ev = &field.enumerated_values[0];
                    let ux_type = rust_type_for_field_width(field.bit_width);
                    let mut writer_full = writer_line.clone();

                    if is_bit {
                        // BitWriter - no extra writer impl for enum
                        field_type_parts.push(writer_full);
                    } else {
                        // FieldWriter - add impl with variant methods
                        // The writer type alias line is followed by "; impl < 'a , REG > WriterName..."
                        let impl_line = render_enum_writer_impl(ev, ename, &field_writer_name, reg_spec, ux_type, config);
                        field_type_parts.push(format!("{} {}", writer_full, impl_line));
                    }
                } else {
                    field_type_parts.push(writer_line);
                }
            } else {
                field_type_parts.push(writer_line);
            }
        }
    }

    // Now we have field_type_parts with all the field type definitions
    // The last one needs "impl R {" or "impl W {" appended

    // Determine what impl blocks we need
    let readable_fields: Vec<&&Field> = sorted_fields.iter()
        .filter(|f| is_readable && f.access.as_ref().map_or(true, |a| a.is_readable()))
        .collect();
    let writable_fields: Vec<&&Field> = sorted_fields.iter()
        .filter(|f| is_writable && f.access.as_ref().map_or(true, |a| a.is_writable()))
        .collect();

    // Output all field type lines
    if !field_type_parts.is_empty() {
        let last_idx = field_type_parts.len() - 1;

        // Determine what to append after last field type part
        let first_impl = if !readable_fields.is_empty() {
            " impl R {\n"
        } else if !writable_fields.is_empty() {
            " impl W {\n"
        } else {
            "\n"
        };

        for (i, part) in field_type_parts.iter().enumerate() {
            out.push_str(part);
            if i == last_idx {
                out.push_str(first_impl);
            } else {
                out.push('\n');
            }
        }
    } else if !readable_fields.is_empty() {
        out.push_str("impl R {\n");
    } else if !writable_fields.is_empty() {
        out.push_str("impl W {\n");
    }

    // Generate reader methods
    if !readable_fields.is_empty() {
        let last_rf_idx = readable_fields.len() - 1;

        for (i, field) in readable_fields.iter().enumerate() {
            let field_accessor = apply_ident_format(config, "field_accessor", &field.name);
            let field_reader_name = apply_ident_format(config, "field_reader", &field.name);
            let desc = field.description.as_deref().unwrap_or("");
            let is_bit = field.bit_width == 1;

            let bits_desc = if is_bit {
                format!("Bit {} - {}", field.bit_offset, desc)
            } else {
                format!("Bits {}:{} - {}", field.bit_offset, field.bit_offset + field.bit_width - 1, desc)
            };

            out.push_str(&format!("#[doc = {:?}]\n", bits_desc));

            let fn_body = if is_bit {
                format!("#[inline (always)] pub fn {} (& self) -> {} {{ {} :: new ((self . bits & {}) != 0) }}",
                    field_accessor, field_reader_name, field_reader_name,
                    1u64 << field.bit_offset)
            } else {
                let shift = field.bit_offset;
                let mask = field_mask(field.bit_width);
                let result_type = rust_type_for_field_width(field.bit_width);

                if shift == 0 {
                    format!("#[inline (always)] pub fn {} (& self) -> {} {{ {} :: new ((self . bits & {}) as {}) }}",
                        field_accessor, field_reader_name, field_reader_name, mask, result_type)
                } else {
                    format!("#[inline (always)] pub fn {} (& self) -> {} {{ {} :: new (((self . bits >> {}) & {}) as {}) }}",
                        field_accessor, field_reader_name, field_reader_name, shift, mask, result_type)
                }
            };

            out.push_str(&fn_body);

            if i == last_rf_idx {
                // Last reader method: close impl R, optionally open impl W
                if !writable_fields.is_empty() {
