pub fn render_register(
    out: &mut String,
    r: &Register,
    peripheral: &Peripheral,
    device: &Device,
    config: &Config,
) -> Result<(), String> {
    let reg_name = apply_ident_format(config, "register", &r.name);
    let reg_spec = format!("{}Spec", reg_name); // Same as reg_name + "Spec"
    let reg_mod = apply_ident_format(config, "register_mod", &r.name);

    let is_readable = r.access.is_readable();
    let is_writable = r.access.is_writable();
    let has_fields = !r.fields.is_empty();

