        let one_bitmap = calculate_one_bitmap(&r.fields, r.size, &r.modified_write_values);
        let zero_bitmap = calculate_zero_bitmap(&r.fields, r.size);

        let mut writable_extras = String::new();
        if one_bitmap != 0 {
            writable_extras.push_str(&format!(" const ONE_TO_MODIFY_FIELDS_BITMAP : {} = {} ;",
                rust_type_str, format_hex(one_bitmap, r.size)));
        }
        if zero_bitmap != 0 {
            writable_extras.push_str(&format!(" const ZERO_TO_MODIFY_FIELDS_BITMAP : {} = {} ;",
                rust_type_str, format_hex(zero_bitmap, r.size)));
        }

        out.push_str(&format!("#[doc = \"`write(|w| ..)` method takes [`{}::W`](W) writer structure\"] impl crate :: Writable for {} {{ type Safety = crate :: Unsafe ;{} }}\n",
            reg_mod, reg_spec, writable_extras));
    }

    // Resettable impl
    let reset_val = r.reset_value;
    let reset_doc = format!("`reset()` method sets {} to value {}", r.name, format_hex(reset_val, r.size));

    if reset_val == 0 {
        out.push_str(&format!("#[doc = {:?}] impl crate :: Resettable for {} {{ }}\n", reset_doc, reg_spec));
    } else {
        out.push_str(&format!("#[doc = {:?}] impl crate :: Resettable for {} {{ const RESET_VALUE : {} = {} ; }}\n",
            reset_doc, reg_spec, rust_type_str, format_hex(reset_val, r.size)));
    }

    out.push_str("}"); // close register mod - NO newline here, caller adds "}\n" for the peripheral mod
    out.push_str(" }\n"); // close register mod with proper spacing

    Ok(())
}

pub fn render_register_array(
    out: &mut String,
    ra: &RegisterArray,
    peripheral: &Peripheral,
    device: &Device,
    config: &Config,
) -> Result<(), String> {
    let base_name = ra.name.replace("%s", "").trim_end_matches('_').to_string();
    let reg_name = apply_ident_format(config, "register", &base_name);
    let reg_spec = format!("{}Spec", reg_name);
    let reg_mod = apply_ident_format(config, "register_mod", &base_name);

    let is_readable = ra.access.is_readable();
    let is_writable = ra.access.is_writable();
    let has_fields = !ra.fields.is_empty();
    let desc = ra.description.as_deref().unwrap_or("");

    let accessor_doc = build_accessor_doc(&ra.name, &reg_mod, desc, is_readable, is_writable, has_fields);

    out.push_str(&format!("#[doc = {:?}]\n", accessor_doc));
    out.push_str(&format!("#[doc (alias = {:?})] pub type {} = crate :: Reg < {} :: {} > ;\n",
        ra.name, reg_name, reg_mod, reg_spec));

    out.push_str(&format!("#[doc = {:?}] pub mod {} {{\n", desc, reg_mod));

    if is_readable {
        out.push_str(&format!("#[doc = \"Register `{}` reader\"] pub type R = crate :: R < {} > ;\n",
            ra.name, reg_spec));
    }
    if is_writable {
        out.push_str(&format!("#[doc = \"Register `{}` writer\"] pub type W = crate :: W < {} > ;\n",
            ra.name, reg_spec));
    }

    if has_fields {
        render_fields(out, &ra.fields, &reg_name, &reg_spec, &reg_mod, is_readable, is_writable, ra.size, config)?;
    } else {
        render_no_fields(out, &reg_name, &reg_spec, is_readable, is_writable, config);
    }

    let rust_type_str = rust_type(ra.size);
    let desc_full = build_register_spec_doc(&ra.name, &reg_mod, desc, is_readable, is_writable);

    out.push_str(&format!("#[doc = {:?}] pub struct {} ; impl crate :: RegisterSpec for {} {{ type Ux = {} ; }}\n",
        desc_full, reg_spec, reg_spec, rust_type_str));

    if is_readable {
        out.push_str(&format!("#[doc = \"`read()` method returns [`{}::R`](R) reader structure\"] impl crate :: Readable for {} {{ }}\n",
            reg_mod, reg_spec));
    }
    if is_writable {
        out.push_str(&format!("#[doc = \"`write(|w| ..)` method takes [`{}::W`](W) writer structure\"] impl crate :: Writable for {} {{ type Safety = crate :: Unsafe ; }}\n",
            reg_mod, reg_spec));
    }

    let reset_val = ra.reset_value;
    let reset_doc = format!("`reset()` method sets {} to value {}", ra.name, format_hex(reset_val, ra.size));
    if reset_val == 0 {
        out.push_str(&format!("#[doc = {:?}] impl crate :: Resettable for {} {{ }}\n", reset_doc, reg_spec));
    } else {
        out.push_str(&format!("#[doc = {:?}] impl crate :: Resettable for {} {{ const RESET_VALUE : {} = {} ; }}\n",
            reset_doc, reg_spec, rust_type_str, format_hex(reset_val, ra.size)));
    }

    out.push_str("} }\n"); // close register mod

    Ok(())
}

fn render_no_fields(out: &mut String, reg_name: &str, reg_spec: &str, is_readable: bool, is_writable: bool, config: &Config) {
    if !is_readable && is_writable {
        // write-only, no fields
        out.push_str(&format!(" impl core :: fmt :: Debug for crate :: generic :: Reg < {} > {{ fn fmt (& self , f : & mut core :: fmt :: Formatter < '_ >) -> core :: fmt :: Result {{ write ! (f , \"(not readable)\") }} }}", reg_spec));
        out.push_str(" impl W { }\n");
    } else if is_readable && !is_writable {
        // read-only, no fields
        out.push_str(" impl core :: fmt :: Debug for R { fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result { write ! (f , \"{}\" , self . bits ()) } }\n");
    } else {
        // read-write, no fields
        out.push_str(" impl core :: fmt :: Debug for R { fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result { write ! (f , \"{}\" , self . bits ()) } }");
        out.push_str(" impl W { }\n");
    }
}

struct FieldTypeOutput {
    lines: Vec<String>,       // Lines before "impl R {"
    has_trailing_close: bool, // Whether the last line ends with "}" (from enum impl)
}

fn render_fields(
    out: &mut String,
    fields: &[Field],
    reg_name: &str,
    reg_spec: &str,
    reg_mod: &str,
    is_readable: bool,
    is_writable: bool,
    reg_size: u32,
    config: &Config,
) -> Result<(), String> {
    // Sort fields by bit offset
    let mut sorted_fields: Vec<&Field> = fields.iter().collect();
    sorted_fields.sort_by_key(|f| f.bit_offset);

    // We need to collect all the field type definitions first
    // The last one gets "impl R {" or relevant impl appended to it

    let mut field_type_parts: Vec<String> = Vec::new();

    for field in &sorted_fields {
        let field_name_orig = &field.name;
        let field_accessor = apply_ident_format(config, "field_accessor", field_name_orig);
        let field_reader_name = apply_ident_format(config, "field_reader", field_name_orig);
        let field_writer_name = apply_ident_format(config, "field_writer", field_name_orig);

        let desc = field.description.as_deref().unwrap_or("");
        let is_bit = field.bit_width == 1;

        let has_enum = !field.enumerated_values.is_empty();

        let field_eff_readable = is_readable && field.access.as_ref().map_or(true, |a| a.is_readable());
        let field_eff_writable = is_writable && field.access.as_ref().map_or(true, |a| a.is_writable());

        // Get enum name 
        let enum_name_opt = if has_enum {
            let ev = &field.enumerated_values[0];
            let raw_name = if let Some(ref n) = ev.name {
                if !n.is_empty() && !config.field_names_for_enums {
                    n.clone()
                } else {
                    field_name_orig.clone()
                }
            } else {
                field_name_orig.clone()
            };
            Some(apply_ident_format(config, "enum_name", &raw_name))
        } else {
            None
        };

        // Field reader type alias
        if field_eff_readable {
            let reader_line = if is_bit {
                if let Some(ref ename) = enum_name_opt {
                    format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: BitReader < {} > ;",
                        field_name_orig, desc, field_reader_name, ename)
                } else {
                    format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: BitReader ;",
                        field_name_orig, desc, field_reader_name)
                }
            } else {
                if let Some(ref ename) = enum_name_opt {
                    format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: FieldReader < {} > ;",
                        field_name_orig, desc, field_reader_name, ename)
                } else {
                    format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: FieldReader ;",
                        field_name_orig, desc, field_reader_name)
                }
            };
            field_type_parts.push(reader_line);
        }

        // Enum definitions and impl
        if has_enum {
            let ev = &field.enumerated_values[0];
            let enum_lines = render_enum_type(ev, field_name_orig, field.bit_width, config)?;
            for line in enum_lines {
                field_type_parts.push(line);
            }
        }

        // Field writer type alias (and possibly enum writer impl)
        if field_eff_writable {
            let writer_type = get_bit_writer_type(&field.modified_write_values);

            let writer_line = if is_bit {
                if let Some(ref ename) = enum_name_opt {
                    format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: {} < 'a , REG , {} > ;",
                        field_name_orig, desc, field_writer_name, writer_type, ename)
                } else {
                    format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: {} < 'a , REG > ;",
                        field_name_orig, desc, field_writer_name, writer_type)
                }
            } else {
                if let Some(ref ename) = enum_name_opt {
                    format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: FieldWriter < 'a , REG , {} , {} > ;",
                        field_name_orig, desc, field_writer_name, field.bit_width, ename)
                } else {
                    format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: FieldWriter < 'a , REG , {} > ;",
                        field_name_orig, desc, field_writer_name, field.bit_width)
                }
            };

            if has_enum {
                // Append enum writer impl to the writer type alias line
                if let Some(ref ename) = enum_name_opt {
                    let ev = &field.enumerated_values[0];
                    let ux_type = rust_type_for_field_width(field.bit_width);
                    let mut writer_full = writer_line.clone();

                    if is_bit {
                        // BitWriter - no extra writer impl for enum
                        field_type_parts.push(writer_full);
                    } else {
                        // FieldWriter - add impl with variant methods
                        // The writer type alias line is followed by "; impl < 'a , REG > WriterName..."
                        let impl_line = render_enum_writer_impl(ev, ename, &field_writer_name, reg_spec, ux_type, config);
                        field_type_parts.push(format!("{} {}", writer_full, impl_line));
                    }
                } else {
                    field_type_parts.push(writer_line);
                }
            } else {
                field_type_parts.push(writer_line);
            }
        }
    }

    // Now we have field_type_parts with all the field type definitions
    // The last one needs "impl R {" or "impl W {" appended

    // Determine what impl blocks we need
    let readable_fields: Vec<&&Field> = sorted_fields.iter()
        .filter(|f| is_readable && f.access.as_ref().map_or(true, |a| a.is_readable()))
        .collect();
    let writable_fields: Vec<&&Field> = sorted_fields.iter()
        .filter(|f| is_writable && f.access.as_ref().map_or(true, |a| a.is_writable()))
        .collect();

    // Output all field type lines
    if !field_type_parts.is_empty() {
        let last_idx = field_type_parts.len() - 1;

        // Determine what to append after last field type part
        let first_impl = if !readable_fields.is_empty() {
            " impl R {\n"
        } else if !writable_fields.is_empty() {
            " impl W {\n"
        } else {
            "\n"
        };

        for (i, part) in field_type_parts.iter().enumerate() {
            out.push_str(part);
            if i == last_idx {
                out.push_str(first_impl);
            } else {
                out.push('\n');
            }
        }
    } else if !readable_fields.is_empty() {
        out.push_str("impl R {\n");
    } else if !writable_fields.is_empty() {
        out.push_str("impl W {\n");
    }

    // Generate reader methods
    if !readable_fields.is_empty() {
        let last_rf_idx = readable_fields.len() - 1;

        for (i, field) in readable_fields.iter().enumerate() {
            let field_accessor = apply_ident_format(config, "field_accessor", &field.name);
            let field_reader_name = apply_ident_format(config, "field_reader", &field.name);
            let desc = field.description.as_deref().unwrap_or("");
            let is_bit = field.bit_width == 1;

            let bits_desc = if is_bit {
                format!("Bit {} - {}", field.bit_offset, desc)
            } else {
                format!("Bits {}:{} - {}", field.bit_offset, field.bit_offset + field.bit_width - 1, desc)
            };

            out.push_str(&format!("#[doc = {:?}]\n", bits_desc));

            let fn_body = if is_bit {
                format!("#[inline (always)] pub fn {} (& self) -> {} {{ {} :: new ((self . bits & {}) != 0) }}",
                    field_accessor, field_reader_name, field_reader_name,
                    1u64 << field.bit_offset)
            } else {
                let shift = field.bit_offset;
                let mask = field_mask(field.bit_width);
                let result_type = rust_type_for_field_width(field.bit_width);

                if shift == 0 {
                    format!("#[inline (always)] pub fn {} (& self) -> {} {{ {} :: new ((self . bits & {}) as {}) }}",
                        field_accessor, field_reader_name, field_reader_name, mask, result_type)
                } else {
                    format!("#[inline (always)] pub fn {} (& self) -> {} {{ {} :: new (((self . bits >> {}) & {}) as {}) }}",
                        field_accessor, field_reader_name, field_reader_name, shift, mask, result_type)
                }
            };

            out.push_str(&fn_body);

            if i == last_rf_idx {
                // Last reader method: close impl R, optionally open impl W
                if !writable_fields.is_empty() {
                    out.push_str(" } impl W {\n");
                } else {
                    out.push_str(" }\n");
                }
            } else {
                out.push('\n');
            }
        }
    }

    // Generate writer methods
    if !writable_fields.is_empty() {
        let last_wf_idx = writable_fields.len() - 1;

        for (i, field) in writable_fields.iter().enumerate() {
            let field_accessor = apply_ident_format(config, "field_accessor", &field.name);
            let field_writer_name = apply_ident_format(config, "field_writer", &field.name);
            let desc = field.description.as_deref().unwrap_or("");
            let is_bit = field.bit_width == 1;

            let bits_desc = if is_bit {
                format!("Bit {} - {}", field.bit_offset, desc)
            } else {
                format!("Bits {}:{} - {}", field.bit_offset, field.bit_offset + field.bit_width - 1, desc)
            };

            out.push_str(&format!("#[doc = {:?}]\n", bits_desc));

            let fn_body = format!("#[inline (always)] pub fn {} (& mut self) -> {} < '_ , {} > {{ {} :: new (self , {}) }}",
                field_accessor, field_writer_name, reg_spec, field_writer_name, field.bit_offset);

            out.push_str(&fn_body);

            if i == last_wf_idx {
                out.push_str(" }\n");
            } else {
                out.push('\n');
            }
        }
    }

    // If no fields in impl blocks but we opened impl R
    if readable_fields.is_empty() && writable_fields.is_empty() {
        // Do nothing, already handled
    }

    Ok(())
}

fn render_enum_type(
    ev: &EnumeratedValues,
    field_name: &str,
    bit_width: u32,
    config: &Config,
) -> Result<Vec<String>, String> {
    let mut lines = Vec::new();

    let raw_name = if let Some(ref n) = ev.name {
        if !n.is_empty() && !config.field_names_for_enums {
            n.clone()
        } else {
            field_name.to_string()
        }
    } else {
        field_name.to_string()
    };

    let enum_name = apply_ident_format(config, "enum_name", &raw_name);
    let repr_type = rust_type_for_field_width(bit_width);

    // Get default value for "Value on reset"
    let reset_val = 0u64; // TODO: get from register reset value

    let desc_line = format!("#[doc = \"{}\\n\\nValue on reset: {}\"]", raw_name, reset_val);
    lines.push(desc_line);
    lines.push("#[derive (Clone , Copy , Debug , PartialEq , Eq)]".to_string());

    // Build enum body
    let mut enum_body = format!("#[repr ({})] pub enum {} {{", repr_type, enum_name);
    for val in &ev.values {
        if val.is_default { continue; }
        if let Some(ref v) = val.value {
            let v_num = match v {
                EnumValue::Value(n) => *n,
                EnumValue::Default => continue,
            };
            let variant_name = apply_ident_format(config, "enum_value", &val.name);
            let val_desc = val.description.as_deref().unwrap_or("");
            enum_body.push_str(&format!("\n#[doc = \"{}: {}\"] {} = {} ,", 
                v_num, escape_doc(val_desc), variant_name, v_num));
        }
    }

    // Add From impl and FieldSpec impl on same line as closing brace
    enum_body.push_str(&format!(
        " }} impl From < {} > for {} {{\n#[inline (always)] fn from (variant : {}) -> Self {{ variant as _ }} }} impl crate :: FieldSpec for {} {{ type Ux = {} ; }} impl crate :: IsEnum for {} {{ }}",
        enum_name, repr_type, enum_name, enum_name, repr_type, enum_name
    ));
    lines.push(enum_body);

    // Reader impl - appended to last reader type alias
    // This is added in the field_reader type alias section
    let field_reader_name = apply_ident_format(config, "field_reader", &raw_name);

    // Reader impl methods
    let mut reader_impl = format!("impl {} {{\n", field_reader_name);
    reader_impl.push_str("#[doc = \"Get enumerated values variant\"]\n");

    // variant() method
    let mut variant_match = format!("#[inline (always)] pub const fn variant (& self) -> Option < {} > {{ match self . bits {{", enum_name);
    for val in &ev.values {
        if val.is_default { continue; }
        if let Some(ref v) = val.value {
            let v_num = match v {
                EnumValue::Value(n) => *n,
                EnumValue::Default => continue,
            };
            let variant_name = apply_ident_format(config, "enum_value", &val.name);
            variant_match.push_str(&format!(" {} => Some ({} :: {}) ,", v_num, enum_name, variant_name));
        }
    }
    variant_match.push_str(" _ => None , } }");
    reader_impl.push_str(&variant_match);
    reader_impl.push('\n');

    // is_xxx() methods
    let vals_with_values: Vec<&EnumeratedValue> = ev.values.iter()
        .filter(|v| !v.is_default && v.value.is_some())
        .collect();

    for (i, val) in vals_with_values.iter().enumerate() {
        if let Some(ref v) = val.value {
            let v_num = match v {
                EnumValue::Value(n) => *n,
                EnumValue::Default => continue,
            };
            let variant_name = apply_ident_format(config, "enum_value", &val.name);
            let accessor_name = apply_ident_format(config, "enum_value_accessor", &val.name);
            let val_desc = val.description.as_deref().unwrap_or("");

            reader_impl.push_str(&format!("#[doc = {:?}]\n", val_desc));
            let is_fn = format!("#[inline (always)] pub fn {} (& self) -> bool {{ * self == {} :: {} }}", 
                accessor_name, enum_name, variant_name);
            reader_impl.push_str(&is_fn);
            if i < vals_with_values.len() - 1 {
                reader_impl.push('\n');
            }
        }
    }

    reader_impl.push_str(" }\n");
    lines.push(reader_impl);

    Ok(lines)
}

fn render_enum_writer_impl(
    ev: &EnumeratedValues,
    enum_name: &str,
    field_writer_name: &str,
    reg_spec: &str,
    ux_type: &str,
    config: &Config,
) -> String {
    let mut s = format!("impl < 'a , REG > {} < 'a , REG > where REG : crate :: Writable + crate :: RegisterSpec , REG :: Ux : From < {} > {{\n",
        field_writer_name, ux_type);

    let vals_with_values: Vec<&EnumeratedValue> = ev.values.iter()
        .filter(|v| !v.is_default && v.value.is_some())
        .collect();

    for (i, val) in vals_with_values.iter().enumerate() {
        if let Some(ref v) = val.value {
            let v_num = match v {
                EnumValue::Value(n) => *n,
                EnumValue::Default => continue,
            };
            let variant_name = apply_ident_format(config, "enum_value", &val.name);
            let accessor_name = apply_ident_format(config, "enum_value_accessor", &val.name);
            let val_desc = val.description.as_deref().unwrap_or("");

            s.push_str(&format!("#[doc = {:?}]\n", val_desc));
            let fn_line = format!("#[inline (always)] pub fn {} (self) -> & 'a mut crate :: W < REG > {{ self . variant ({} :: {}) }}",
                accessor_name, enum_name, variant_name);
            s.push_str(&fn_line);
            if i < vals_with_values.len() - 1 {
                s.push('\n');
            }
        }
    }

    s.push_str(" }");
    s
}

fn build_accessor_doc(reg_name: &str, reg_mod: &str, desc: &str, readable: bool, writable: bool, has_fields: bool) -> String {
    let access_str = match (readable, writable) {
        (true, true) => "rw",
        (true, false) => "r",
        (false, true) => "w",
        _ => "rw",
    };

    let mut doc = format!("{} ({}) register accessor: {}", reg_name, access_str, desc);
    doc.push_str("\n\n");

    if readable {
        if writable {
            doc.push_str(&format!(
                "You can [`read`](crate::Reg::read) this register and get [`{}::R`]. ",
                reg_mod
            ));
        } else {
            doc.push_str(&format!(
                "You can [`read`](crate::Reg::read) this register and get [`{}::R`].",
                reg_mod
            ));
        }
    }

    if writable {
        doc.push_str(&format!(
            "You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`]. ",
            reg_mod
        ));
        if readable {
            doc.push_str("You can also [`modify`](crate::Reg::modify) this register. ");
        }
    }

    if readable || writable {
        doc.push_str("See [API](https://docs.rs/svd2rust/#read--modify--write-api).");
    }

    if has_fields {
        doc.push_str(&format!("\n\nFor information about available fields see [`mod@{}`] module", reg_mod));
    }

    doc
}

fn build_register_spec_doc(reg_name: &str, reg_mod: &str, desc: &str, readable: bool, writable: bool) -> String {
    let mut doc = format!("{}\n\n", desc);

    if readable && writable {
        doc.push_str(&format!(
            "You can [`read`](crate::Reg::read) this register and get [`{}::R`](R). You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`](W). You can also [`modify`](crate::Reg::modify) this register. See [API](https://docs.rs/svd2rust/#read--modify--write-api).",
            reg_mod, reg_mod
        ));
    } else if readable {
        doc.push_str(&format!(
            "You can [`read`](crate::Reg::read) this register and get [`{}::R`](R). See [API](https://docs.rs/svd2rust/#read--modify--write-api).",
            reg_mod
        ));
    } else if writable {
        doc.push_str(&format!(
            "You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`](W). See [API](https://docs.rs/svd2rust/#read--modify--write-api).",
            reg_mod
        ));
    }

    doc
}

fn calculate_zero_bitmap(fields: &[Field], reg_size: u32) -> u64 {
    let mut bitmap = 0u64;
    for f in fields {
        match &f.modified_write_values {
            Some(ModifiedWriteValues::ZeroToSet) | 
            Some(ModifiedWriteValues::ZeroToClear) |
            Some(ModifiedWriteValues::ZeroToToggle) => {
                let mask = field_mask(f.bit_width) << f.bit_offset;
                bitmap |= mask;
            },
            _ => {}
        }
    }
    bitmap
}

fn calculate_one_bitmap(fields: &[Field], reg_size: u32, reg_mwv: &Option<ModifiedWriteValues>) -> u64 {
    let mut bitmap = 0u64;
    for f in fields {
        let mwv = f.modified_write_values.as_ref().or(reg_mwv.as_ref());
        match mwv {
            Some(ModifiedWriteValues::OneToClear) |
            Some(ModifiedWriteValues::OneToSet) |
            Some(ModifiedWriteValues::OneToToggle) => {
                let mask = field_mask(f.bit_width) << f.bit_offset;
                bitmap |= mask;
            },
            _ => {}
        }
    }
    bitmap
}

fn get_bit_writer_type(mwv: &Option<ModifiedWriteValues>) -> &'static str {
    match mwv {
        Some(ModifiedWriteValues::OneToClear) => "BitWriter1C",
        Some(ModifiedWriteValues::OneToSet) => "BitWriter1S",
        Some(ModifiedWriteValues::OneToToggle) => "BitWriter1T",
        Some(ModifiedWriteValues::ZeroToClear) => "BitWriter0C",
        Some(ModifiedWriteValues::ZeroToSet) => "BitWriter0S",
        Some(ModifiedWriteValues::ZeroToToggle) => "BitWriter0T",
        _ => "BitWriter",
    }
}

fn rust_type_for_field_width(width: u32) -> &'static str {
    match width {
        1..=8 => "u8",
        9..=16 => "u16",
        17..=32 => "u32",
        _ => "u64",
    }
}
