        out.push_str(&format!("#[doc = {:?}] impl crate :: Resettable for {} {{ }}", reset_doc, reg_spec));
    } else {
        out.push_str(&format!("#[doc = {:?}] impl crate :: Resettable for {} {{ const RESET_VALUE : {} = {} ; }}",
            reset_doc, reg_spec, rust_type_str, format_hex(reset_val, ra.size)));
    }

    out.push_str(" }"); // close register mod

    Ok(())
}

fn render_no_fields(out: &mut String, reg_name: &str, reg_spec: &str, is_readable: bool, is_writable: bool, config: &Config) {
    if !is_readable && is_writable {
        // write-only, no fields
        out.push_str(&format!(" impl core :: fmt :: Debug for crate :: generic :: Reg < {} > {{ fn fmt (& self , f : & mut core :: fmt :: Formatter < '_ >) -> core :: fmt :: Result {{ write ! (f , \"(not readable)\") }} }}", reg_spec));
        out.push_str(" impl W { }\n");
    } else if is_readable && !is_writable {
        // read-only, no fields
        out.push_str(" impl core :: fmt :: Debug for R { fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result { write ! (f , \"{}\" , self . bits ()) } }\n");
    } else {
        // read-write, no fields
        out.push_str(" impl core :: fmt :: Debug for R { fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result { write ! (f , \"{}\" , self . bits ()) } }");
        out.push_str(" impl W { }\n");
    }
}

fn render_fields(
    out: &mut String,
    fields: &[Field],
    reg_name: &str,
    reg_spec: &str,
    reg_mod: &str,
    is_readable: bool,
    is_writable: bool,
    reg_size: u32,
    reg_reset: u64,
    config: &Config,
) -> Result<(), String> {
    // Sort fields by bit offset
    let mut sorted_fields: Vec<&Field> = fields.iter().collect();
    sorted_fields.sort_by_key(|f| f.bit_offset);

    // Collect all field type definitions and their impls in order
    let mut field_type_sections: Vec<String> = Vec::new();

    // Also collect last part for "impl R {" connection
    let mut last_is_writer_with_enum = false;

    for field in &sorted_fields {
        let field_name_orig = &field.name;
        let field_accessor = apply_ident_format(config, "field_accessor", field_name_orig);
        let field_reader_name = apply_ident_format(config, "field_reader", field_name_orig);
        let field_writer_name = apply_ident_format(config, "field_writer", field_name_orig);

        let desc = field.description.as_deref().unwrap_or("");
        let is_bit = field.bit_width == 1;

        let has_enum = !field.enumerated_values.is_empty();

        let field_eff_readable = is_readable && field.access.as_ref().map_or(true, |a| a.is_readable());
        let field_eff_writable = is_writable && field.access.as_ref().map_or(true, |a| a.is_writable());

        // Get enum display name and Rust name
        let (enum_display_name, enum_rust_name) = if has_enum {
            let ev = &field.enumerated_values[0];
            let raw_name = if let Some(ref n) = ev.name {
                if !n.is_empty() && !config.field_names_for_enums {
                    n.clone()
                } else {
                    field_name_orig.clone()
                }
            } else {
                field_name_orig.clone()
            };
            let rust_name = apply_ident_format(config, "enum_name", &raw_name);
            (raw_name, rust_name)
        } else {
            (String::new(), String::new())
        };

        let enum_name_opt = if has_enum { Some(enum_rust_name.as_str()) } else { None };

        // Field WITHOUT enum: reader type and writer type on separate lines
        if !has_enum {
            if field_eff_readable {
                let reader_line = build_reader_type_line(field_name_orig, desc, &field_reader_name, 
                    is_bit, None, config);
                field_type_sections.push(reader_line);
            }
            if field_eff_writable {
                let writer_line = build_writer_type_line(field_name_orig, desc, &field_writer_name,
                    is_bit, field.bit_width, None, &field.modified_write_values, config);
                field_type_sections.push(writer_line);
                last_is_writer_with_enum = false;
            }
        } else {
            // Field WITH enum:
            // 1. Enum definition
            let ev = &field.enumerated_values[0];
            let enum_lines = render_enum_type_lines(ev, &enum_display_name, &enum_rust_name, 
                field.bit_width, reg_reset, field.bit_offset, config)?;
            for line in enum_lines {
                field_type_sections.push(line);
            }

            // 2. Reader type + impl ModeR { ... }  (if readable)
            if field_eff_readable {
                let reader_type_line = build_reader_type_line(field_name_orig, desc, &field_reader_name,
                    is_bit, Some(&enum_rust_name), config);
                // Add impl reader methods inline
                let impl_reader = render_enum_reader_impl(ev, &enum_display_name, &enum_rust_name, 
                    &field_reader_name, field.bit_width, config);
                // Line: "reader_type_line impl FieldReader { ... }"
                let combined = format!("{} {}", reader_type_line, impl_reader);
                field_type_sections.push(combined);
            }

            // 3. Writer type + impl WriterName { ... }  (if writable)
            if field_eff_writable {
                let writer_type_line = build_writer_type_line(field_name_orig, desc, &field_writer_name,
                    is_bit, field.bit_width, Some(&enum_rust_name), &field.modified_write_values, config);
                // Add impl writer methods inline
                let ux_type = rust_type_for_field_width(field.bit_width);
                let impl_writer = render_enum_writer_impl(ev, &enum_rust_name, &field_writer_name, ux_type, config);
                let combined = format!("{} {}", writer_type_line, impl_writer);
                field_type_sections.push(combined);
                last_is_writer_with_enum = true;
            }
        }
    }

    // Determine what impl blocks to add
    let readable_fields: Vec<&&Field> = sorted_fields.iter()
        .filter(|f| is_readable && f.access.as_ref().map_or(true, |a| a.is_readable()))
        .collect();
    let writable_fields: Vec<&&Field> = sorted_fields.iter()
        .filter(|f| is_writable && f.access.as_ref().map_or(true, |a| a.is_writable()))
        .collect();

    // Output field type sections
    if !field_type_sections.is_empty() {
        let last_idx = field_type_sections.len() - 1;

        // What to append after last field type section
        let first_impl_open = if !readable_fields.is_empty() {
            " impl R {\n"
        } else if !writable_fields.is_empty() {
            " impl W {\n"
        } else {
            "\n"
        };

        for (i, section) in field_type_sections.iter().enumerate() {
            out.push_str(section);
            if i == last_idx {
                out.push_str(first_impl_open);
            } else {
                out.push('\n');
            }
        }
    } else if !readable_fields.is_empty() {
        out.push_str("impl R {\n");
    } else if !writable_fields.is_empty() {
        out.push_str("impl W {\n");
    }

    // Generate reader methods in impl R
    if !readable_fields.is_empty() {
        let last_rf_idx = readable_fields.len() - 1;

        for (i, field) in readable_fields.iter().enumerate() {
            let field_accessor = apply_ident_format(config, "field_accessor", &field.name);
            let field_reader_name = apply_ident_format(config, "field_reader", &field.name);
            let desc = field.description.as_deref().unwrap_or("");
            let is_bit = field.bit_width == 1;

            let bits_desc = build_bits_desc(field);
            out.push_str(&format!("#[doc = {:?}]\n", bits_desc));

            let fn_body = build_reader_fn_body(&field_accessor, &field_reader_name, 
                field.bit_offset, field.bit_width, is_bit, reg_size);
            out.push_str(&fn_body);

            if i == last_rf_idx {
                if !writable_fields.is_empty() {
                    out.push_str(" } impl W {\n");
                } else {
                    out.push_str(" }\n");
                }
            } else {
                out.push('\n');
            }
        }
    }

    // Generate writer methods in impl W
    if !writable_fields.is_empty() {
        let last_wf_idx = writable_fields.len() - 1;

        for (i, field) in writable_fields.iter().enumerate() {
            let field_accessor = apply_ident_format(config, "field_accessor", &field.name);
            let field_writer_name = apply_ident_format(config, "field_writer", &field.name);
            let desc = field.description.as_deref().unwrap_or("");

            let bits_desc = build_bits_desc(field);
            out.push_str(&format!("#[doc = {:?}]\n", bits_desc));

            let fn_line = format!("#[inline (always)] pub fn {} (& mut self) -> {} < '_ , {} > {{ {} :: new (self , {}) }}",
                field_accessor, field_writer_name, reg_spec, field_writer_name, field.bit_offset);
            out.push_str(&fn_line);

            if i == last_wf_idx {
                out.push_str(" }\n");
            } else {
                out.push('\n');
            }
        }
    }

    Ok(())
}

fn build_bits_desc(field: &Field) -> String {
    let desc = field.description.as_deref().unwrap_or("");
    if field.bit_width == 1 {
        format!("Bit {} - {}", field.bit_offset, desc)
    } else {
        format!("Bits {}:{} - {}", field.bit_offset, field.bit_offset + field.bit_width - 1, desc)
    }
}

fn build_reader_type_line(field_name: &str, desc: &str, reader_name: &str, is_bit: bool, 
    enum_name: Option<&str>, config: &Config) -> String {
    if is_bit {
        if let Some(ename) = enum_name {
            format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: BitReader < {} > ;",
                field_name, desc, reader_name, ename)
        } else {
            format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: BitReader ;",
                field_name, desc, reader_name)
        }
    } else {
        if let Some(ename) = enum_name {
            format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: FieldReader < {} > ;",
                field_name, desc, reader_name, ename)
        } else {
            format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: FieldReader ;",
                field_name, desc, reader_name)
        }
    }
}

fn build_writer_type_line(field_name: &str, desc: &str, writer_name: &str, is_bit: bool,
    bit_width: u32, enum_name: Option<&str>, mwv: &Option<ModifiedWriteValues>, config: &Config) -> String {
    let writer_type = get_bit_writer_type(mwv);

    if is_bit {
        if let Some(ename) = enum_name {
            format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: {} < 'a , REG , {} > ;",
                field_name, desc, writer_name, writer_type, ename)
        } else {
            format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: {} < 'a , REG > ;",
                field_name, desc, writer_name, writer_type)
        }
    } else {
        if let Some(ename) = enum_name {
            format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: FieldWriter < 'a , REG , {} , {} > ;",
                field_name, desc, writer_name, bit_width, ename)
        } else {
            format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: FieldWriter < 'a , REG , {} > ;",
                field_name, desc, writer_name, bit_width)
        }
    }
}

fn build_reader_fn_body(accessor: &str, reader_name: &str, bit_offset: u32, bit_width: u32, 
    is_bit: bool, reg_size: u32) -> String {
    if is_bit {
        format!("#[inline (always)] pub fn {} (& self) -> {} {{ {} :: new ((self . bits & {}) != 0) }}",
            accessor, reader_name, reader_name, 1u64 << bit_offset)
    } else {
        let shift = bit_offset;
        let mask = field_mask(bit_width);
        let result_type = rust_type_for_field_width(bit_width);

        if shift == 0 {
            format!("#[inline (always)] pub fn {} (& self) -> {} {{ {} :: new ((self . bits & {}) as {}) }}",
                accessor, reader_name, reader_name, mask, result_type)
        } else {
            format!("#[inline (always)] pub fn {} (& self) -> {} {{ {} :: new (((self . bits >> {}) & {}) as {}) }}",
                accessor, reader_name, reader_name, shift, mask, result_type)
        }
    }
}

fn render_enum_type_lines(
    ev: &EnumeratedValues,
    display_name: &str,
    enum_rust_name: &str,
    bit_width: u32,
    reg_reset: u64,
    bit_offset: u32,
    config: &Config,
) -> Result<Vec<String>, String> {
    let mut lines = Vec::new();

    let repr_type = rust_type_for_field_width(bit_width);

    // Extract field reset value from register reset
    let field_reset = (reg_reset >> bit_offset) & field_mask(bit_width);

    // Doc line: use PascalCase of enum name (display name PascalCased)
    let doc_name = crate::config::to_pascal_case(display_name);
    lines.push(format!("#[doc = \"{}\\n\\nValue on reset: {}\"]", doc_name, field_reset));
    lines.push("#[derive (Clone , Copy , Debug , PartialEq , Eq)]".to_string());

    // Enum body
    let mut enum_body = format!("#[repr ({})] pub enum {} {{", repr_type, enum_rust_name);
    for val in &ev.values {
        if val.is_default { continue; }
        if let Some(ref v) = val.value {
            let v_num = match v {
                EnumValue::Value(n) => *n,
                EnumValue::Default => continue,
            };
            let variant_name = apply_ident_format(config, "enum_value", &val.name);
            let val_desc = val.description.as_deref().unwrap_or("");
            enum_body.push_str(&format!("\n#[doc = \"{}: {}\"] {} = {} ,",
                v_num, escape_doc(val_desc), variant_name, v_num));
        }
    }

    // Close enum and add From impl + FieldSpec impl + IsEnum impl
    enum_body.push_str(&format!(
        " }} impl From < {} > for {} {{\n#[inline (always)] fn from (variant : {}) -> Self {{ variant as _ }} }} impl crate :: FieldSpec for {} {{ type Ux = {} ; }} impl crate :: IsEnum for {} {{ }}",
        enum_rust_name, repr_type, enum_rust_name, enum_rust_name, repr_type, enum_rust_name
    ));
    lines.push(enum_body);

    Ok(lines)
}

fn render_enum_reader_impl(
    ev: &EnumeratedValues,
    display_name: &str,
    enum_rust_name: &str,
    reader_name: &str,
    bit_width: u32,
    config: &Config,
) -> String {
    let mut s = format!("impl {} {{\n", reader_name);
    s.push_str("#[doc = \"Get enumerated values variant\"]\n");

    // variant() method
    let mut match_arms = String::new();
    let vals_with_values: Vec<&EnumeratedValue> = ev.values.iter()
        .filter(|v| !v.is_default && v.value.is_some())
        .collect();

    for val in &vals_with_values {
        if let Some(ref v) = val.value {
            let v_num = match v {
                EnumValue::Value(n) => *n,
                EnumValue::Default => continue,
            };
            let variant_name = apply_ident_format(config, "enum_value", &val.name);
            match_arms.push_str(&format!(" {} => Some ({} :: {}) ,", v_num, enum_rust_name, variant_name));
        }
    }

    s.push_str(&format!("#[inline (always)] pub const fn variant (& self) -> Option < {} > {{ match self . bits {{{} _ => None , }} }}\n",
        enum_rust_name, match_arms));

    // is_xxx() methods (with is_ prefix)
    for (i, val) in vals_with_values.iter().enumerate() {
        if let Some(ref v) = val.value {
            let v_num = match v {
                EnumValue::Value(n) => *n,
                EnumValue::Default => continue,
            };
            let variant_name = apply_ident_format(config, "enum_value", &val.name);
            let accessor_snake = apply_ident_format(config, "enum_value_accessor", &val.name);
            let is_accessor = format!("is_{}", accessor_snake);
            let val_desc = val.description.as_deref().unwrap_or("");

            s.push_str(&format!("#[doc = {:?}]\n", val_desc));
            let is_fn = format!("#[inline (always)] pub fn {} (& self) -> bool {{ * self == {} :: {} }}",
                is_accessor, enum_rust_name, variant_name);
            s.push_str(&is_fn);
            if i < vals_with_values.len() - 1 {
                s.push('\n');
            }
        }
    }

    s.push_str(" }"); // close impl reader
    s
}

fn render_enum_writer_impl(
    ev: &EnumeratedValues,
    enum_rust_name: &str,
    writer_name: &str,
    ux_type: &str,
    config: &Config,
) -> String {
    let mut s = format!("impl < 'a , REG > {} < 'a , REG > where REG : crate :: Writable + crate :: RegisterSpec , REG :: Ux : From < {} > {{\n",
        writer_name, ux_type);

    let vals_with_values: Vec<&EnumeratedValue> = ev.values.iter()
        .filter(|v| !v.is_default && v.value.is_some())
        .collect();

    for (i, val) in vals_with_values.iter().enumerate() {
        if let Some(ref v) = val.value {
            let v_num = match v {
                EnumValue::Value(n) => *n,
                EnumValue::Default => continue,
            };
            let variant_name = apply_ident_format(config, "enum_value", &val.name);
            let accessor_name = apply_ident_format(config, "enum_value_accessor", &val.name);
            let val_desc = val.description.as_deref().unwrap_or("");

            s.push_str(&format!("#[doc = {:?}]\n", val_desc));
            let fn_line = format!("#[inline (always)] pub fn {} (self) -> & 'a mut crate :: W < REG > {{ self . variant ({} :: {}) }}",
                accessor_name, enum_rust_name, variant_name);
            s.push_str(&fn_line);
            if i < vals_with_values.len() - 1 {
                s.push('\n');
            }
        }
    }

    s.push_str(" }");
    s
}

fn build_accessor_doc(reg_name: &str, reg_mod: &str, desc: &str, readable: bool, writable: bool, has_fields: bool) -> String {
    let access_str = match (readable, writable) {
        (true, true) => "rw",
        (true, false) => "r",
        (false, true) => "w",
        _ => "rw",
    };

    let mut doc = format!("{} ({}) register accessor: {}", reg_name, access_str, desc);
    doc.push_str("\n\n");

    if readable {
        if writable {
            doc.push_str(&format!(
                "You can [`read`](crate::Reg::read) this register and get [`{}::R`]. ",
                reg_mod
            ));
        } else {
            doc.push_str(&format!(
                "You can [`read`](crate::Reg::read) this register and get [`{}::R`].",
                reg_mod
            ));
        }
    }

    if writable {
        doc.push_str(&format!(
            "You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`]. ",
            reg_mod
        ));
        if readable {
            doc.push_str("You can also [`modify`](crate::Reg::modify) this register. ");
        }
    }

    if readable || writable {
        doc.push_str("See [API](https://docs.rs/svd2rust/#read--modify--write-api).");
    }

    if has_fields {
        doc.push_str(&format!("\n\nFor information about available fields see [`mod@{}`] module", reg_mod));
    }

    doc
}

fn build_register_spec_doc(reg_name: &str, reg_mod: &str, desc: &str, readable: bool, writable: bool) -> String {
    let mut doc = format!("{}\n\n", desc);

    if readable && writable {
        doc.push_str(&format!(
            "You can [`read`](crate::Reg::read) this register and get [`{}::R`](R). You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`](W). You can also [`modify`](crate::Reg::modify) this register. See [API](https://docs.rs/svd2rust/#read--modify--write-api).",
            reg_mod, reg_mod
        ));
    } else if readable {
        doc.push_str(&format!(
            "You can [`read`](crate::Reg::read) this register and get [`{}::R`](R). See [API](https://docs.rs/svd2rust/#read--modify--write-api).",
            reg_mod
        ));
    } else if writable {
        doc.push_str(&format!(
            "You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`](W). See [API](https://docs.rs/svd2rust/#read--modify--write-api).",
            reg_mod
        ));
    }

    doc
}

fn format_reset_val(val: u64, bits: u32) -> String {
    if val == 0 {
        "0".to_string()
    } else {
        format_hex(val, bits)
    }
}

fn calculate_zero_bitmap(fields: &[Field], reg_size: u32) -> u64 {
    let mut bitmap = 0u64;
    for f in fields {
        match &f.modified_write_values {
            Some(ModifiedWriteValues::ZeroToSet) | 
            Some(ModifiedWriteValues::ZeroToClear) |
            Some(ModifiedWriteValues::ZeroToToggle) => {
                let mask = field_mask(f.bit_width) << f.bit_offset;
                bitmap |= mask;
            },
            _ => {}
        }
    }
    bitmap
}

fn calculate_one_bitmap(fields: &[Field], reg_size: u32, reg_mwv: &Option<ModifiedWriteValues>) -> u64 {
    let mut bitmap = 0u64;
    for f in fields {
        let mwv = f.modified_write_values.as_ref().or(reg_mwv.as_ref());
        match mwv {
            Some(ModifiedWriteValues::OneToClear) |
            Some(ModifiedWriteValues::OneToSet) |
            Some(ModifiedWriteValues::OneToToggle) => {
                let mask = field_mask(f.bit_width) << f.bit_offset;
                bitmap |= mask;
            },
            _ => {}
        }
    }
    bitmap
}

fn get_bit_writer_type(mwv: &Option<ModifiedWriteValues>) -> &'static str {
    match mwv {
        Some(ModifiedWriteValues::OneToClear) => "BitWriter1C",
        Some(ModifiedWriteValues::OneToSet) => "BitWriter1S",
        Some(ModifiedWriteValues::OneToToggle) => "BitWriter1T",
        Some(ModifiedWriteValues::ZeroToClear) => "BitWriter0C",
        Some(ModifiedWriteValues::ZeroToSet) => "BitWriter0S",
        Some(ModifiedWriteValues::ZeroToToggle) => "BitWriter0T",
        _ => "BitWriter",
    }
}

fn rust_type_for_field_width(width: u32) -> &'static str {
    match width {
        1..=8 => "u8",
        9..=16 => "u16",
        17..=32 => "u32",
        _ => "u64",
    }
}
