# The issue is that render_no_fields starts with " impl" (space before impl) which shouldn't be on new line
# But the reader type alias already ends with ";\n" so it IS on a new line
# Expected output:
# "#[doc = "Register `RO_REG` reader"] pub type R = crate :: R < RoRegSpec > ; impl core :: fmt :: Debug for R ..."
# So the "impl Debug for R" is on the SAME LINE as the type R alias!
# There's just a space separator: "...RoRegSpec > ; impl core::fmt::Debug..."

# In my code, register.rs outputs:
# "#[doc = "..."] pub type R = ...; \n" (with newline)
# Then render_no_fields adds " impl core::fmt::Debug..."
# This creates a newline between type R and impl Debug

# Fix: the R/W type aliases should NOT have "\n" at the end when no-fields
# OR: render_no_fields should be called before the type aliases are finalized

# Actually, looking at the pattern more carefully:
# The R type alias + Debug impl are on the SAME LINE in no-fields case
# And W type alias + impl W {} are on same line too

# The simplest fix: in render_no_fields, don't use "\n" after type alias
# But the register.rs outputs the type aliases first, then calls render_no_fields

# I need to change the register output to handle no-fields case differently

# For no-fields registers:
# "pub type R = crate :: R < RoRegSpec > ;" + " impl core :: fmt :: Debug for R { ... }" on SAME LINE
# (not ending with \n for the type alias in no-fields case)

# Let me fix the type alias output to strip trailing newline before render_no_fields is called

python3 << 'EOF'
with open('/workspace/impl/src/generate/register.rs', 'r') as f:
    content = f.read()

# Change the R and W type alias outputs when no fields to not add newline
# They currently add "\n" at end
# We need them to NOT add "\n" when no fields

# The approach: after outputting R/W type aliases, if no fields, strip the last \n
# and call render_no_fields which will add the impl on same line

# Actually the fix is simpler: change render_no_fields to NOT start with "\n"
# and in render_register/render_register_array, when !has_fields,
# change the R type alias to not have trailing "\n"

# Find the pattern where R/W type aliases are output
old_r_alias = '''    if is_readable {
        out.push_str(&format!("#[doc = \\"Register `{}` reader\\"] pub type R = crate :: R < {} > ;\\n",
            r.name, reg_spec));
    }
    if is_writable {
        out.push_str(&format!("#[doc = \\"Register `{}` writer\\"] pub type W = crate :: W < {} > ;\\n",
            r.name, reg_spec));
    }

    if has_fields {'''

new_r_alias = '''    if is_readable {
        let trail = if has_fields { "\\n" } else { "" };
        out.push_str(&format!("#[doc = \\"Register `{}` reader\\"] pub type R = crate :: R < {} > ;{}", 
            r.name, reg_spec, trail));
    }
    if is_writable {
        let trail = if has_fields { "\\n" } else { "" };
        out.push_str(&format!("#[doc = \\"Register `{}` writer\\"] pub type W = crate :: W < {} > ;{}", 
            r.name, reg_spec, trail));
    }

    if has_fields {'''

content = content.replace(old_r_alias, new_r_alias)

# Same fix for render_register_array
old_ra_alias = '''    if is_readable {
        out.push_str(&format!("#[doc = \\"Register `{}` reader\\"] pub type R = crate :: R < {} > ;\\n",
            ra.name, reg_spec));
    }
    if is_writable {
        out.push_str(&format!("#[doc = \\"Register `{}` writer\\"] pub type W = crate :: W < {} > ;\\n",
            ra.name, reg_spec));
    }

    if has_fields {'''

new_ra_alias = '''    if is_readable {
        let trail = if has_fields { "\\n" } else { "" };
        out.push_str(&format!("#[doc = \\"Register `{}` reader\\"] pub type R = crate :: R < {} > ;{}",
            ra.name, reg_spec, trail));
    }
    if is_writable {
        let trail = if has_fields { "\\n" } else { "" };
        out.push_str(&format!("#[doc = \\"Register `{}` writer\\"] pub type W = crate :: W < {} > ;{}",
            ra.name, reg_spec, trail));
    }

    if has_fields {'''

content = content.replace(old_ra_alias, new_ra_alias)

with open('/workspace/impl/src/generate/register.rs', 'w') as f:
    f.write(content)
print("Fixed type alias trailing newline")
EOF

