fn render_riscv_interrupts(out: &mut String, interrupts: &[&Interrupt], device: &Device, config: &Config) -> Result<(), String> {
    // Check if there's a settings file with RISC-V config
    if config.settings.riscv_config.is_none() {
        log_warn("svd2rust::generate::device", "No settings file provided for RISC-V target. Using legacy interrupts rendering");
        log_warn("svd2rust::generate::device", "Please, consider migrating your PAC to riscv 0.12.0 or later");
    }

    // extern "C" block for interrupt handlers (BEFORE vector union in RISCV)
    if !interrupts.is_empty() {
        out.push_str("#[cfg (feature = \"rt\")] extern \"C\" {");
        for irq in interrupts {
            let irq_name = apply_ident_format(config, "interrupt", &irq.name);
            out.push_str(&format!(" fn {} () ;", irq_name));
        }
        out.push_str(" }\n");
    }

    // Vector union type (different for RISC-V)
    out.push_str("#[doc (hidden)]\n");
    out.push_str("#[repr (C)] pub union Vector { pub _handler : unsafe extern \"C\" fn () , pub _reserved : usize , }\n");

    // External interrupts table
    if interrupts.is_empty() {
        out.push_str("#[no_mangle] pub static __EXTERNAL_INTERRUPTS : [Vector ; 0] = [] ;\n");
    } else {
        let max_irq = interrupts.iter().map(|i| i.value).max().unwrap_or(0);
        let count = max_irq + 1;

        out.push_str("#[cfg (feature = \"rt\")]\n");
        out.push_str("#[doc (hidden)]\n");
        out.push_str(&format!("#[no_mangle] pub static __EXTERNAL_INTERRUPTS : [Vector ; {}] = [", count));

        let mut irq_map: HashMap<u32, &Interrupt> = HashMap::new();
        for irq in interrupts {
            irq_map.insert(irq.value, irq);
        }

        for i in 0..count {
            if let Some(irq) = irq_map.get(&i) {
                let irq_name = apply_ident_format(config, "interrupt", &irq.name);
                out.push_str(&format!("Vector {{ _handler : {} }} , ", irq_name));
            } else {
                out.push_str("Vector { _reserved : 0 } , ");
            }
        }
        if out.ends_with(' ') { out.pop(); }
        out.push_str("] ;\n");
    }

    // Interrupt module for RISC-V
    out.push_str("#[doc (hidden)] pub mod interrupt {\n");
    out.push_str("#[doc = r\"Enumeration of all the interrupts.\"]\n");
    out.push_str("#[derive (Copy , Clone , Debug , PartialEq , Eq)]\n");

    if interrupts.is_empty() {
        out.push_str("#[repr (u16)] pub enum Interrupt { }\n");
    } else {
        out.push_str("#[repr (u16)] pub enum Interrupt {\n");
        let irq_count = interrupts.len();
        for (irq_idx, irq) in interrupts.iter().enumerate() {
            let irq_name = apply_ident_format(config, "interrupt", &irq.name);
            let desc = irq.description.as_deref().unwrap_or("");
            let line_end = if irq_idx < irq_count - 1 { "\n" } else { " " };
            out.push_str(&format!("#[doc = \"{} - {}\"] {} = {} ,{}",
                irq.value, escape_doc(desc), irq_name, irq.value, line_end));
        }
        out.push_str("}\n");
    }

    // TryFromInterruptError and impl
    out.push_str("#[doc = r\" TryFromInterruptError\"]\n");
    out.push_str("#[derive (Debug , Copy , Clone)] pub struct TryFromInterruptError (()) ; impl Interrupt {\n");
    out.push_str("#[doc = r\" Attempt to convert a given value into an `Interrupt`\"]\n");
    out.push_str("#[inline] pub fn try_from (value : u8) -> Result < Self , TryFromInterruptError > { match value {");
    for irq in interrupts {
        let irq_name = apply_ident_format(config, "interrupt", &irq.name);
        out.push_str(&format!(" {} => Ok (Interrupt :: {}) ,", irq.value, irq_name));
    }
    out.push_str(" _ => Err (TryFromInterruptError (())) , } } }\n");

    // interrupt! macro (when rt feature)
    out.push_str("#[cfg (feature = \"rt\")]\n");
    out.push_str("#[macro_export]\n");
    out.push_str("#[doc = r\" Assigns a handler to an interrupt\"]\n");
    out.push_str("#[doc = r\"\"]\n");
    out.push_str("#[doc = r\" This macro takes two arguments: the name of an interrupt and the path to the\"]\n");
    out.push_str("#[doc = r\" function that will be used as the handler of that interrupt. That function\"]\n");
    out.push_str("#[doc = r\" must have signature `fn()`.\"]\n");
    out.push_str("#[doc = r\"\"]\n");
    out.push_str("#[doc = r\" Optionally, a third argument may be used to declare interrupt local data.\"]\n");
    out.push_str("#[doc = r\" The handler will have exclusive access to these *local* variables on each\"]\n");
    out.push_str("#[doc = r\" invocation. If the third argument is used then the signature of the handler\"]\n");
    out.push_str("#[doc = r\" function must be `fn(&mut $NAME::Locals)` where `$NAME` is the first argument\"]\n");
    out.push_str("#[doc = r\" passed to the macro.\"]\n");
    out.push_str("#[doc = r\"\"]\n");
    out.push_str("#[doc = r\" # Example\"]\n");
    out.push_str("#[doc = r\"\"]\n");
    out.push_str("#[doc = r\" ``` ignore\"]\n");
    out.push_str("#[doc = r\" interrupt!(TIM2, periodic);\"]\n");
    out.push_str("#[doc = r\"\"]\n");
    out.push_str("#[doc = r\" fn periodic() {\"]\n");
    out.push_str("#[doc = r#\"     print!(\".\");\"#]\n");
    out.push_str("#[doc = r\" }\"]\n");
    out.push_str("#[doc = r\"\"]\n");
    out.push_str("#[doc = r\" interrupt!(TIM3, tick, locals: {\"]\n");
    out.push_str("#[doc = r\"     tick: bool = false;\"]\n");
    out.push_str("#[doc = r\" });\"]\n");
    out.push_str("#[doc = r\"\"]\n");
    out.push_str("#[doc = r\" fn tick(locals: &mut TIM3::Locals) {\"]\n");
    out.push_str("#[doc = r\"     locals.tick = !locals.tick;\"]\n");
    out.push_str("#[doc = r\"\"]\n");
    out.push_str("#[doc = r\"     if locals.tick {\"]\n");
    out.push_str("#[doc = r#\"         println!(\"Tick\");\"#]\n");
    out.push_str("#[doc = r\"     } else {\"]\n");
    out.push_str("#[doc = r#\"         println!(\"Tock\");\"#]\n");
    out.push_str("#[doc = r\"     }\"]\n");
    out.push_str("#[doc = r\" }\"]\n");
    out.push_str("#[doc = r\" ```\"] macro_rules ! interrupt { ($ NAME : ident , $ path : path , locals : { $ ($ lvar : ident : $ lty : ty = $ lval : expr ;) * }) => {\n");
    out.push_str("#[allow (non_snake_case)] mod $ NAME { pub struct Locals { $ (pub $ lvar : $ lty ,) * } }\n");
    out.push_str("#[allow (non_snake_case)]\n");
    out.push_str("#[no_mangle] pub extern \"C\" fn $ NAME () { let _ = $ crate :: interrupt :: Interrupt :: $ NAME ; static mut LOCALS : self :: $ NAME :: Locals = self :: $ NAME :: Locals { $ ($ lvar : $ lval ,) * } ; let f : fn (& mut self :: $ NAME :: Locals) = $ path ; f (unsafe { & mut LOCALS }) ; } } ; ($ NAME : ident , $ path : path) => {\n");
    out.push_str("#[allow (non_snake_case)]\n");
    out.push_str("#[no_mangle] pub extern \"C\" fn $ NAME () { let _ = $ crate :: interrupt :: Interrupt :: $ NAME ; let f : fn () = $ path ; f () ; } } } }");

    out.push_str("\n}\n"); // close pub mod interrupt

    // pub use self::interrupt::Interrupt;
    if !interrupts.is_empty() {
        out.push_str("pub use self :: interrupt :: Interrupt ;\n");
    }

    Ok(())
}
