depth = 0
i = start_pos + len(start_marker)
while i < len(content):
    if content[i] == '{': depth += 1
    elif content[i] == '}':
        if depth == 0:
            end_pos = i + 1
            break
        depth -= 1
    i += 1

old_func = content[start_pos:end_pos]
