new_func = '''fn render_msp430_interrupts(out: &mut String, interrupts: &[&Interrupt], config: &Config) -> Result<(), String> {
    // MSP430 uses msp430-interrupt ABI
    if !interrupts.is_empty() {
        out.push_str("#[cfg (feature = \\"rt\\")] extern \\"msp430-interrupt\\" {");
        for irq in interrupts {
            let irq_name = apply_ident_format(config, "interrupt", &irq.name);
            out.push_str(&format!(" fn {} () ;", irq_name));
        }
        out.push_str(" }\\n");
    } else {
        out.push_str("#[cfg (feature = \\"rt\\")] extern \\"msp430-interrupt\\" { }\\n");
    }

    // Vector union (u16 reserved for MSP430)
    out.push_str("#[doc (hidden)]\\n");
    out.push_str("#[repr (C)] pub union Vector { _handler : unsafe extern \\"msp430-interrupt\\" fn () , _reserved : u16 , }\\n");

    // Interrupt table
    if interrupts.is_empty() {
        out.push_str("#[cfg (feature = \\"rt\\")]\\n");
        out.push_str("#[doc (hidden)]\\n");
        out.push_str("#[link_section = \\".vector_table.interrupts\\"]\\n");
        out.push_str("#[no_mangle]\\n");
        out.push_str("#[used] pub static __INTERRUPTS : [Vector ; 0] = [] ;\\n");
    } else {
        let max_irq = interrupts.iter().map(|i| i.value).max().unwrap_or(0);
        let count = max_irq + 1;

        out.push_str("#[cfg (feature = \\"rt\\")]\\n");
        out.push_str("#[doc (hidden)]\\n");
        out.push_str("#[link_section = \\".vector_table.interrupts\\"]\\n");
        out.push_str("#[no_mangle]\\n");
        out.push_str(&format!("#[used] pub static __INTERRUPTS : [Vector ; {}] = [", count));

        let mut irq_map: HashMap<u32, &Interrupt> = HashMap::new();
        for irq in interrupts {
            irq_map.insert(irq.value, irq);
        }

        for i in 0..count {
            if let Some(irq) = irq_map.get(&i) {
                let irq_name = apply_ident_format(config, "interrupt", &irq.name);
                out.push_str(&format!("Vector {{ _handler : {} }} , ", irq_name));
            } else {
                out.push_str("Vector { _reserved : 0 } , ");
            }
        }
        if out.ends_with(\' \') { out.pop(); }
        out.push_str("] ;\\n");
    }

    // Interrupt enum (MSP430-specific doc)
    out.push_str("#[doc = r\\"Enumeration of all the interrupts. This enum is seldom used in application or library crates. It is present primarily for documenting the device\'s implemented interrupts.\\"]\\n");

    if interrupts.is_empty() {
        out.push_str("#[derive (Copy , Clone , Debug , PartialEq , Eq)] pub enum Interrupt { }\\n");
    } else {
        out.push_str("#[derive (Copy , Clone , Debug , PartialEq , Eq)]\\n");
        out.push_str("#[repr (u16)] pub enum Interrupt {\\n");
        let irq_count = interrupts.len();
        for (irq_idx, irq) in interrupts.iter().enumerate() {
            let irq_name = apply_ident_format(config, "interrupt", &irq.name);
            let desc = irq.description.as_deref().unwrap_or("");
            let line_end = if irq_idx < irq_count - 1 { "\\n" } else { " " };
            out.push_str(&format!("#[doc = \\"{} - {}\\"] {} = {} ,{}",
                irq.value, escape_doc(desc), irq_name, irq.value, line_end));
        }
        out.push_str("} unsafe impl msp430 :: abi :: Interrupt for Interrupt {\\n");
        out.push_str("#[inline (always)] fn nr (& self) -> usize { * self as usize } }\\n");
    }

    Ok(())
}'''

